const STRINGS={
  en:{home:'Home',phasing:'Phasing plan',risk:'At-risk depts',orders:'Orders needed',tasks:'Tasks',blockers:'Blockers',team:'My team',fixtures:'Fixtures',checkedIn:'Checked in',notCheckedIn:'Not checked in',quickActions:'Quick actions',back:'Back',continue:'Continue',review:'Review',confirm:'Confirm',cancel:'Cancel',close:'Close'},
  es:{home:'Inicio',phasing:'Plan de fases',risk:'Deptos. en riesgo',orders:'Pedidos necesarios',tasks:'Tareas',blockers:'Bloqueos',team:'Mi equipo',fixtures:'Mobiliario',checkedIn:'Registrado',notCheckedIn:'No registrado',quickActions:'Acciones rápidas',back:'Atrás',continue:'Continuar',review:'Revisar',confirm:'Confirmar',cancel:'Cancelar',close:'Cerrar'}
};
const DEPT_ES={'Grocery & Consumables':'Comestibles y Consumibles','Produce':'Productos Frescos','Bakery & Deli':'Panadería y Charcutería','Pharmacy':'Farmacia','Health & Beauty':'Salud y Belleza','Apparel':'Ropa','Electronics':'Electrónica','Home & Domestics':'Hogar y Domésticos','Jewelry':'Joyería'};

let state=loadState();
let activeProjectId=state.activeProjectId||'USRM-012759';
