function deepClone(v){return JSON.parse(JSON.stringify(v))}
function loadState(){
  try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.projects&&parsed.projects.length)return parsed;}}catch(e){}
  return {projects:deepClone(seedProjects),activeProjectId:'USRM-012759',language:'en'};
}
function saveState(){state.activeProjectId=activeProjectId;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){}}
function project(){return state.projects.find(p=>p.id===activeProjectId)||state.projects[0]}
function department(idOrName){const p=project();return p.departments.find(d=>d.id===idOrName||d.name===idOrName)}
function taskById(id){return project().tasks.find(t=>t.id===id)}
function blockerById(id){return project().blockers.find(b=>b.id===id)}
function t(key){return (STRINGS[state.language]&&STRINGS[state.language][key])||STRINGS.en[key]||key}
function deptLabel(name){return state.language==='es'?(DEPT_ES[name]||name):name}
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function fmtDate(value){if(!value)return '—';const d=new Date(value+'T00:00:00');return d.toLocaleDateString(state.language==='es'?'es-ES':'en-US',{month:'short',day:'numeric'})}
function daysBetween(a,b){return Math.max(0,Math.round((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/86400000))}
function initials(name){return (name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function openTaskStates(){return ['ASSIGNED','IN_PROGRESS','PENDING_REVIEW','PAUSED']}
function gap(item){return Math.max(0,item.ordered-item.received)}
function riskClass(r){return r==='AT RISK'?'red':r==='WATCH'?'amber':'green'}
function statusClass(s){return s==='COMPLETE'?'green':s==='IN PROGRESS'?'blue':'purple'}
function itemStatusClass(s){return s==='RECEIVED'?'green':s==='PARTIAL'?'amber':'red'}
function priorityClass(p){return p==='HIGH'?'red':p==='MEDIUM'?'amber':'gray'}
function riskText(r){if(state.language==='es')return r==='AT RISK'?'EN RIESGO':r==='WATCH'?'VIGILAR':'A TIEMPO';return r}
function statusText(s){if(state.language==='es')return s==='COMPLETE'?'COMPLETADO':s==='IN PROGRESS'?'EN PROGRESO':'PRÓXIMO';return s}
function itemStatusText(s){if(state.language==='es')return s==='RECEIVED'?'RECIBIDO':s==='PARTIAL'?'PARCIAL':s==='DELAYED'?'RETRASADO':'NO ENVIADO';return s}
function calcProject(p){
  let ordered=0,received=0;
  p.departments.forEach(d=>{let od=0,rc=0;d.fixtures.forEach(i=>{ordered+=i.ordered;received+=i.received;od+=i.ordered;rc+=i.received;});if(od)d.fixturePct=Math.round(rc/od*100);if(d.fixtures.length&&d.fixtures.every(i=>gap(i)===0)){d.risk='ON TRACK';d.reason=null;d.location='Fully received — put away in department';}});
  p.overallFixture=ordered?Math.round(received/ordered*100):0;
  p.atRisk=p.departments.filter(d=>d.risk==='AT RISK').length;
  p.watch=p.departments.filter(d=>d.risk==='WATCH').length;
  p.openTasks=p.tasks.filter(t=>openTaskStates().includes(t.status)).length;
  p.openBlockers=p.blockers.filter(b=>b.status==='OPEN').length;
  p.daysToGoLive=daysBetween(DEMO_TODAY,p.goLive);
  return p;
}
function addActivity(type,label,meta={}){const p=project();p.activities.unshift({id:'ACT-'+Date.now(),type,label,time:new Date().toISOString(),...meta});saveState()}
function nextBlockerId(p){const max=(p.blockers||[]).reduce((m,b)=>{const hit=String(b.id||'').match(/-BLK-(\d+)$/);return Math.max(m,hit?Number(hit[1]):0)},0);return `${p.id}-BLK-${max+1}`}
function renderAll(){calcProject(project());renderHeader();renderShortcuts();renderCurrentView()}
function renderHeader(){
  const p=calcProject(project());
  document.getElementById('checkStatus').innerHTML=`<span class="status-dot ${p.checkedIn?'on':''}"></span> ${p.checkedIn?t('checkedIn'):t('notCheckedIn')}`;
  const riskBadge=p.focus?`<span class="project-badge focus">🚩 FOCUS</span>`:(p.atRisk?`<span class="project-badge">${p.atRisk} ${state.language==='es'?'EN RIESGO':'AT RISK'}</span>`:'');
  document.getElementById('projectCard').innerHTML=`<span class="project-icon">🏬</span><span class="project-copy"><span class="project-title">${state.language==='es'?'Tienda':'Store'} ${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</span><span class="project-meta">${esc(p.id)} · RPM ${esc(p.rpm)} · ${esc(p.phase)} · ${p.daysToGoLive} ${state.language==='es'?'días para apertura':'days to go-live'}</span></span>${riskBadge}<span class="project-chevron">▾</span>`;
  document.getElementById('langBtn').textContent=state.language==='es'?'ES':'EN';
  document.getElementById('assistantInput').placeholder=state.language==='es'?'Pregunta sobre fases, mobiliario, pedidos…':'Ask about phasing, fixtures, orders…';
}
function renderShortcuts(){
  const list=[['phasing','📋',t('phasing')],['risk','⚠️',t('risk')],['orders','📦',t('orders')],['tasks','✅',t('tasks')],['blockers','🚧',t('blockers')]];
  document.getElementById('shortcutBar').innerHTML=list.map(([screen,icon,label])=>`<button class="chip ${currentView.screen===screen?'active':''}" onclick="go('${screen}')">${icon} ${esc(label)}</button>`).join('');
}
function pageHead(title,sub=''){return `<div class="page-head"><button class="back-btn" onclick="back()" aria-label="Back">‹</button><div><div class="page-title">${esc(title)}</div>${sub?`<div class="page-sub">${esc(sub)}</div>`:''}</div></div>`}
function badge(text,cls){return `<span class="badge ${cls}">${esc(text)}</span>`}
function progress(pct,kind='blue'){return `<div class="progress-row"><div class="progress ${kind}"><span style="width:${Math.max(0,Math.min(100,pct))}%"></span></div><div class="progress-label">${pct}%</div></div>`}
function go(screen,params={},replace=false){if(!replace)navHistory.push(deepClone(currentView));currentView={screen,params};renderAll();document.getElementById('main').scrollTop=0}
function back(){if(navHistory.length){currentView=navHistory.pop();renderAll();document.getElementById('main').scrollTop=0}else go('home',{},true)}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function showDialog(title,text,actions){
  document.getElementById('dialogTitle').textContent=title;document.getElementById('dialogText').textContent=text;
  document.getElementById('dialogActions').innerHTML=actions.map(a=>`<button class="${a.className||'secondary-btn'}" onclick="${a.action}">${esc(a.label)}</button>`).join('');
  document.getElementById('dialogOverlay').classList.add('open');
}
function closeDialog(){document.getElementById('dialogOverlay').classList.remove('open')}
function showSheet(title,body,search=''){sheetMode=title;document.getElementById('sheetTitle').textContent=title;document.getElementById('sheetBody').innerHTML=body;document.getElementById('sheetSearch').innerHTML=search;document.getElementById('sheetOverlay').classList.add('open')}
function closeSheet(){document.getElementById('sheetOverlay').classList.remove('open');sheetMode=null}
function renderCurrentView(){
  const main=document.getElementById('main');
  const map={home:renderHome,phasing:renderPhasing,risk:renderRisk,department:renderDepartment,fixtures:renderFixtures,orders:renderOrders,tasks:renderTasks,task:renderTaskDetail,team:renderTeam,contacts:renderContacts,blockers:renderBlockers,blocker:renderBlockerDetail,updates:renderUpdates,help:renderHelp};
  main.innerHTML=(map[currentView.screen]||renderHome)(currentView.params||{});
}
function renderHome(){
  const p=calcProject(project());
  const attention=p.departments.filter(d=>d.risk!=='ON TRACK').sort((a,b)=>a.risk===b.risk?0:a.risk==='AT RISK'?-1:1).slice(0,3);
  const overdue=p.tasks.filter(t=>openTaskStates().includes(t.status)&&t.due<DEMO_TODAY).length;
  const greeting=state.language==='es'?`Hola. Estás viendo la Tienda <b>${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</b>.`:`Hi. You’re viewing <b>Store ${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</b>.`;
  const summary=state.language==='es'?`${p.overallFixture}% del mobiliario recibido · ${p.atRisk} depto(s) en riesgo · ${p.openTasks} tareas abiertas · ${p.openBlockers} bloqueo(s) abierto(s).`:`${p.overallFixture}% of fixtures received · ${p.atRisk} department${p.atRisk===1?'':'s'} at risk · ${p.openTasks} open task${p.openTasks===1?'':'s'} · ${p.openBlockers} open blocker${p.openBlockers===1?'':'s'}.`;
  let html=`
    <div style="margin: 4px 0 16px 0; padding: 14px 16px; background: white; border-radius: 14px; border: 1px solid var(--line-soft); box-shadow: var(--shadow);">
      <div style="font-size: 26px; font-weight: 850; color: var(--blue-dark); line-height: 1.2; letter-spacing: -0.02em; margin-bottom: 12px;">
        Hi [' + esc(p.rpm.split(' ')[0]) + '],<br>how can I help you today?
      </div>
      <div style="display: flex; flex-direction: column; align-items: flex-start; gap: 8px;" role="group" aria-label="Suggested Prompts">
        <button type="button" onclick="sendAssistantQuery('View my department schedule')" class="chip" style="height: auto; padding: 8px 14px; border-radius: 20px; font-size: 12px; border: 1px solid #d9e8f8;">View my department schedule</button>
        <button type="button" onclick="sendAssistantQuery('Obtain the necessary PTO sign-offs')" class="chip" style="height: auto; padding: 8px 14px; border-radius: 20px; font-size: 12px; border: 1px solid #d9e8f8;">Obtain the necessary PTO sign-offs</button>
        <button type="button" onclick="sendAssistantQuery('Who called in?')" class="chip" style="height: auto; padding: 8px 14px; border-radius: 20px; font-size: 12px; border: 1px solid #d9e8f8;">Who called in?</button>
        <button type="button" onclick="sendAssistantQuery('Team lead schedule')" class="chip" style="height: auto; padding: 8px 14px; border-radius: 20px; font-size: 12px; border: 1px solid #d9e8f8;">Team lead schedule</button>
        <button type="button" onclick="sendAssistantQuery('Team building some collaboration tools')" class="chip" style="height: auto; padding: 8px 14px; border-radius: 20px; font-size: 12px; border: 1px solid #d9e8f8;">Team building some collaboration tools</button>
      </div>
    </div>
    <div class="chat-row"><div class="assistant-avatar">✦</div><div class="bubble">${greeting}</div></div>
    <div class="chat-row"><div class="assistant-avatar">✦</div><div class="bubble">${summary}<br><b>${state.language==='es'?'¿Qué necesitas revisar hoy?':'What do you need to review today?'}</b></div></div>
    <div class="card">
      <div class="card-title"><span>${state.language==='es'?'Resumen del proyecto':'Project snapshot'}</span><span class="card-sub">${esc(p.id)}</span></div>
      <div class="kpi-grid">
        <div class="kpi"><div class="kpi-number">${p.overallFixture}%</div><div class="kpi-label">${state.language==='es'?'Recibido':'Received'}</div></div>
        <div class="kpi danger"><div class="kpi-number">${p.atRisk}</div><div class="kpi-label">${state.language==='es'?'En riesgo':'At risk'}</div></div>
        <div class="kpi ${overdue?'warn':''}"><div class="kpi-number">${p.openTasks}</div><div class="kpi-label">${state.language==='es'?'Tareas':'Open tasks'}</div></div>
        <div class="kpi ${p.openBlockers?'danger':'good'}"><div class="kpi-number">${p.openBlockers}</div><div class="kpi-label">${state.language==='es'?'Bloqueos':'Blockers'}</div></div>
      </div>
    </div>`;
  if(attention.length){
    html+=`<div class="card"><div class="card-title"><span>${state.language==='es'?'Necesita atención':'Needs attention'}</span><button class="link-btn" onclick="go('risk')">${state.language==='es'?'Ver todo':'View all'}</button></div>`;
    html+=attention.map(d=>`<button class="attention-row" style="width:100%;text-align:left" onclick="go('department',{id:'${d.id}'})"><span class="row-icon">${d.risk==='AT RISK'?'⚠️':'◷'}</span><span class="row-main"><span class="row-title">${esc(deptLabel(d.name))}</span><span class="row-sub">${esc(d.reason?d.reason.label:'')} · ${d.fixturePct}% ${state.language==='es'?'recibido':'received'} · ${fmtDate(d.start)}–${fmtDate(d.end)}</span>${progress(d.fixturePct,riskClass(d.risk))}</span><span>${badge(riskText(d.risk),riskClass(d.risk))}</span></button>`).join('');
    html+='</div>';
  }else{
    html+=`<div class="notice success">✓ ${state.language==='es'?'Todos los departamentos están a tiempo.':'All departments are currently on track.'}</div>`;
  }
  html+=`<div class="card"><div class="card-title"><span>${state.language==='es'?'Acciones de campo':'Field actions'}</span><span class="card-sub">${p.checkedIn?(state.language==='es'?'Sesión activa':'Visit active'):(state.language==='es'?'No registrado':'Not checked in')}</span></div><div class="action-grid">
    <button class="action-tile" onclick="startCheckFlow()"><div class="action-icon">📍</div><div class="action-label">${p.checkedIn?(state.language==='es'?'Salir de tienda':'Check out'):(state.language==='es'?'Registrar llegada':'Check in')}</div><div class="action-desc">${p.checkedIn?(state.language==='es'?'Revisar resumen de visita':'Review visit summary'):(state.language==='es'?'Confirmar tienda y ubicación':'Confirm store and location')}</div></button>
    <button class="action-tile" onclick="openFlow('receive')"><div class="action-icon">▦</div><div class="action-label">${state.language==='es'?'Recibir mobiliario':'Receive fixture'}</div><div class="action-desc">${state.language==='es'?'Escanear, verificar y confirmar':'Scan, verify and confirm'}</div></button>
    <button class="action-tile" onclick="openFlow('dailyUpdate')"><div class="action-icon">📝</div><div class="action-label">${state.language==='es'?'Actualización diaria':'Daily update'}</div><div class="action-desc">${state.language==='es'?'Registrar progreso y riesgos':'Log progress and risks'}</div></button>
    <button class="action-tile" onclick="openFlow('photo')"><div class="action-icon">📷</div><div class="action-label">${state.language==='es'?'Capturar foto':'Capture photo'}</div><div class="action-desc">${state.language==='es'?'Vincular a un registro':'Attach to a record'}</div></button>
  </div></div>`;
  if(p.drafts&&p.drafts.length){html+=`<div class="notice info"><b>${p.drafts.length} ${state.language==='es'?'borrador(es) guardado(s)':'saved draft(s)'}</b><br><button class="link-btn" onclick="openQuickActions()">${state.language==='es'?'Reanudar desde Acciones rápidas':'Resume from Quick actions'}</button></div>`}
  if(p.dailyUpdates.length){const u=p.dailyUpdates[0];html+=`<div class="card compact"><div class="card-title"><span>${state.language==='es'?'Última actualización':'Latest daily update'}</span><button class="link-btn" onclick="go('updates')">${state.language==='es'?'Historial':'History'}</button></div><div class="row-title">${fmtDate(u.date)} · ${esc(u.author)}</div><div class="row-sub">${esc(u.completed||u.progress||'Update submitted')}</div></div>`}
  if(ui.lastQuery){html+=`<div class="chat-row"><div class="assistant-avatar">✦</div><div class="bubble">${ui.lastQuery}</div></div>`;ui.lastQuery=null}
  return html;
}
function setPhasingFilter(value){ui.phasingFilter=value;renderCurrentView()}
function renderPhasing(){
  const p=calcProject(project());let list=p.departments;
  if(ui.phasingFilter==='attention')list=list.filter(d=>d.risk!=='ON TRACK');
  if(ui.phasingFilter==='progress')list=list.filter(d=>d.status==='IN PROGRESS');
  if(ui.phasingFilter==='upcoming')list=list.filter(d=>d.status==='UPCOMING');
  return `${pageHead(t('phasing'),`${p.departments.length} departments · ${p.daysToGoLive} days to go-live`)}
  <div class="card"><div class="card-title"><span>Project timeline</span><span class="card-sub">Possession ${fmtDate(p.possession)} → Go-live ${fmtDate(p.goLive)}</span></div><div class="kpi-grid"><div class="kpi danger"><div class="kpi-number">${p.atRisk}</div><div class="kpi-label">At risk</div></div><div class="kpi warn"><div class="kpi-number">${p.watch}</div><div class="kpi-label">Watch</div></div><div class="kpi"><div class="kpi-number">${p.departments.filter(d=>d.status==='IN PROGRESS').length}</div><div class="kpi-label">In progress</div></div><div class="kpi good"><div class="kpi-number">${p.departments.filter(d=>d.status==='COMPLETE').length}</div><div class="kpi-label">Complete</div></div></div></div>
  <div class="filter-row"><button class="filter-pill ${ui.phasingFilter==='all'?'selected':''}" onclick="setPhasingFilter('all')">All</button><button class="filter-pill ${ui.phasingFilter==='attention'?'selected':''}" onclick="setPhasingFilter('attention')">Needs attention</button><button class="filter-pill ${ui.phasingFilter==='progress'?'selected':''}" onclick="setPhasingFilter('progress')">In progress</button><button class="filter-pill ${ui.phasingFilter==='upcoming'?'selected':''}" onclick="setPhasingFilter('upcoming')">Upcoming</button></div>
  <div class="card"><div class="card-title"><span>Department timeline</span><span class="card-sub">Tap for detail</span></div>${list.length?list.map(d=>`<button class="timeline-row" style="display:block;width:100%;text-align:left" onclick="go('department',{id:'${d.id}'})"><span class="timeline-top"><span><span class="timeline-name">${esc(deptLabel(d.name))}</span><span class="timeline-meta">${fmtDate(d.start)} → ${fmtDate(d.end)} · ${d.fixturePct}% received</span></span><span class="timeline-badges">${badge(statusText(d.status),statusClass(d.status))}${badge(riskText(d.risk),riskClass(d.risk))}</span></span>${d.reason?`<span class="row-sub">${esc(d.reason.label)} — ${esc(d.reason.text)}</span>`:''}${progress(d.fixturePct,riskClass(d.risk))}</button>`).join(''):`<div class="empty"><div class="empty-icon">📋</div><div class="empty-title">No departments in this view</div><div class="empty-text">Change the filter to see the full phasing plan.</div></div>`}</div>`;
}
function renderRisk(){
  const p=calcProject(project());const list=p.departments.filter(d=>d.risk!=='ON TRACK').sort((a,b)=>a.risk===b.risk?0:a.risk==='AT RISK'?-1:1);
  if(!list.length)return `${pageHead(t('risk'),'Priority view')}<div class="card empty"><div class="empty-icon">✓</div><div class="empty-title">All departments are on track</div><div class="empty-text">No active risk flags are present. Review upcoming departments or open tasks next.</div><div class="button-row" style="margin-top:14px"><button class="secondary-btn" onclick="go('phasing')">View phasing</button><button class="primary-btn" onclick="go('tasks')">View tasks</button></div></div>`;
  return `${pageHead(t('risk'),`${list.length} departments need attention`)}<div class="notice warn"><b>Prioritized by severity.</b> Open a department to review evidence and choose the right recovery action.</div>${list.map(d=>`<div class="card"><div class="card-title"><span>${esc(deptLabel(d.name))}</span>${badge(riskText(d.risk),riskClass(d.risk))}</div><div class="row-sub"><b>${esc(d.reason.label)}</b> — ${esc(d.reason.text)}</div><div class="data-grid" style="margin-top:9px"><div class="data-cell"><div class="data-label">Schedule</div><div class="data-value">${fmtDate(d.start)}–${fmtDate(d.end)}</div></div><div class="data-cell"><div class="data-label">Fixture readiness</div><div class="data-value">${d.fixturePct}%</div></div></div>${progress(d.fixturePct,riskClass(d.risk))}<div class="row-actions"><button class="primary-btn small-btn" onclick="go('department',{id:'${d.id}'})">Investigate</button><button class="secondary-btn small-btn" onclick="notifyTeam('${d.id}')">Notify team</button>${d.recommendation?`<button class="secondary-btn small-btn" onclick="openFlow('schedule',{deptId:'${d.id}'})">Review recommendation</button>`:''}</div></div>`).join('')}`;
}
function renderDepartment(params){
  const d=department(params.id);if(!d)return `${pageHead('Department')}<div class="notice danger">Department not found.</div>`;
  const openTasks=project().tasks.filter(t=>t.department===d.name&&openTaskStates().includes(t.status)).length;
  const openBlockers=project().blockers.filter(b=>b.department===d.name&&b.status==='OPEN').length;
  return `${pageHead(deptLabel(d.name),`${statusText(d.status)} · ${fmtDate(d.start)}–${fmtDate(d.end)}`)}
  <div class="card"><div class="card-title"><span>Department status</span><span>${badge(riskText(d.risk),riskClass(d.risk))}</span></div><div class="data-grid"><div class="data-cell"><div class="data-label">Start</div><div class="data-value">${fmtDate(d.start)}</div></div><div class="data-cell"><div class="data-label">End</div><div class="data-value">${fmtDate(d.end)}</div></div><div class="data-cell"><div class="data-label">Fixtures received</div><div class="data-value">${d.fixturePct}%</div></div><div class="data-cell"><div class="data-label">Open work</div><div class="data-value">${openTasks} tasks · ${openBlockers} blockers</div></div></div>${progress(d.fixturePct,riskClass(d.risk))}<div class="row-sub" style="margin-top:7px">📍 ${esc(d.location)}</div></div>
  ${d.reason?`<div class="notice ${d.risk==='AT RISK'?'danger':'warn'}"><b>${esc(d.reason.label)}</b><br>${esc(d.reason.text)}</div>`:`<div class="notice success"><b>On track</b><br>No active risk flags are associated with this department.</div>`}
  ${d.recommendation&&d.recommendation.status==='PROPOSED'?`<div class="card"><div class="card-title"><span>✦ Schedule recommendation</span>${d.recommendation.critical?badge('APPROVAL NEEDED','red'):badge('REVIEW','blue')}</div><div class="date-compare"><div class="date-box"><div class="date-caption">Current</div><div class="date-value">${fmtDate(d.recommendation.oldStart)}–${fmtDate(d.recommendation.oldEnd)}</div></div><div class="date-arrow">→</div><div class="date-box new"><div class="date-caption">Suggested</div><div class="date-value">${fmtDate(d.recommendation.newStart)}–${fmtDate(d.recommendation.newEnd)}</div></div></div><div class="row-sub" style="margin-top:8px">${esc(d.recommendation.ripple)} Go-live buffer: <b>${esc(d.recommendation.buffer)}</b>.</div><button class="secondary-btn full" style="margin-top:9px" onclick="openFlow('schedule',{deptId:'${d.id}'})">Review recommendation</button></div>`:''}
  <div class="section-title">Department actions</div><div class="action-grid">
    <button class="action-tile" onclick="go('fixtures',{deptId:'${d.id}'})"><div class="action-icon">▦</div><div class="action-label">Fixture status</div><div class="action-desc">PO lines, trailers and locations</div></button>
    <button class="action-tile" onclick="go('orders',{deptId:'${d.id}'})"><div class="action-icon">📦</div><div class="action-label">Orders needed</div><div class="action-desc">Review gaps and reorder</div></button>
    <button class="action-tile" onclick="go('tasks',{deptId:'${d.id}'})"><div class="action-icon">✓</div><div class="action-label">Department tasks</div><div class="action-desc">${openTasks} open</div></button>
    <button class="action-tile" onclick="go('contacts',{deptId:'${d.id}'})"><div class="action-icon">☎</div><div class="action-label">Escalation contacts</div><div class="action-desc">Home Office, team and vendor</div></button>
    <button class="action-tile" onclick="openFlow('blocker',{deptId:'${d.id}'})"><div class="action-icon">🚧</div><div class="action-label">Log blocker</div><div class="action-desc">Create with department context</div></button>
    <button class="action-tile" onclick="openFlow('dailyUpdate',{deptId:'${d.id}'})"><div class="action-icon">📝</div><div class="action-label">Add update</div><div class="action-desc">Capture today’s progress</div></button>
  </div>`;
}
function renderFixtures(params){
  const deptId=params.deptId;
  if(!deptId){const p=calcProject(project());return `${pageHead(t('fixtures'),`${p.overallFixture}% received store-wide`)}<div class="card"><div class="card-title"><span>Fixtures by department</span><span class="card-sub">Tap for PO details</span></div>${p.departments.map(d=>`<button class="dept-row" style="width:100%;text-align:left" onclick="go('fixtures',{deptId:'${d.id}'})"><span class="row-main"><span class="row-title">${esc(deptLabel(d.name))}</span><span class="row-sub">${esc(d.location)}</span>${progress(d.fixturePct,riskClass(d.risk))}</span><span>${badge(`${d.fixturePct}%`,riskClass(d.risk))}</span></button>`).join('')}</div>`}
  const d=department(deptId);if(!d)return '';
  const delayed=d.fixtures.filter(i=>['DELAYED','NOT SHIPPED'].includes(i.status)).length;
  return `${pageHead(`${deptLabel(d.name)} fixtures`,`${d.fixtures.length} PO lines · ${d.fixturePct}% received`)}${delayed?`<div class="notice warn"><b>${delayed} delayed or not-shipped line${delayed===1?'':'s'}.</b> Review the responsible trailer or vendor before escalating.</div>`:''}<div class="card"><div class="card-title"><span>Fixture lines</span><button class="link-btn" onclick="openFlow('receive',{deptId:'${d.id}'})">Receive fixture</button></div>${d.fixtures.map(i=>`<div class="fixture-row"><div class="fixture-head"><div><div class="fixture-name">${esc(i.name)}</div><div class="fixture-meta">PO ${esc(i.po)} · ${esc(i.trailer)} · ${esc(i.vendor)}</div></div>${badge(itemStatusText(i.status),itemStatusClass(i.status))}</div><div class="qty-grid"><div class="qty-cell"><div class="qty-num">${i.ordered}</div><div class="qty-label">Ordered</div></div><div class="qty-cell"><div class="qty-num">${i.received}</div><div class="qty-label">Received</div></div><div class="qty-cell"><div class="qty-num">${gap(i)}</div><div class="qty-label">Remaining</div></div></div><div class="fixture-meta">📍 ${esc(i.location)}</div><div class="row-actions"><button class="primary-btn small-btn" ${gap(i)===0?'disabled':''} onclick="openFlow('receive',{deptId:'${d.id}',itemId:'${i.id}'})">Receive</button><button class="secondary-btn small-btn" onclick="openFlow('blocker',{deptId:'${d.id}',fixtureId:'${i.id}'})">Report issue</button><button class="text-btn small-btn" onclick="go('contacts',{deptId:'${d.id}',vendor:'${esc(i.vendor)}'})">Contact vendor</button></div></div>`).join('')}</div>`;
}
function setOrderSelection(key,checked){checked?ui.orderSelection.add(key):ui.orderSelection.delete(key);renderCurrentView()}
function collectShortfalls(deptId){const ds=deptId?[department(deptId)]:project().departments;const arr=[];ds.filter(Boolean).forEach(d=>d.fixtures.forEach(i=>{if(gap(i)>0)arr.push({key:d.id+'::'+i.id,dept:d,item:i,gap:gap(i)})}));return arr.sort((a,b)=>b.gap-a.gap)}
function renderOrders(params){
  const list=collectShortfalls(params.deptId);const title=params.deptId?`${deptLabel(department(params.deptId).name)} orders`:t('orders');const sub=params.deptId?`${list.reduce((s,x)=>s+x.gap,0)} units short`:`${list.reduce((s,x)=>s+x.gap,0)} units short across ${list.length} lines`;
  if(!list.length)return `${pageHead(title,sub)}<div class="card empty"><div class="empty-icon">✓</div><div class="empty-title">No open shortages</div><div class="empty-text">Ordered and received quantities match for this scope.</div><button class="secondary-btn" style="margin-top:14px" onclick="back()">Back to department</button></div>`;
  const validSelected=[...ui.orderSelection].filter(k=>list.some(x=>x.key===k));ui.orderSelection=new Set(validSelected);
  return `${pageHead(title,sub)}<div class="notice info"><b>Select the specific line items to request.</b> Existing requests are shown to prevent duplicates.</div><div class="card"><div class="card-title"><span>Open shortages</span><button class="link-btn" onclick="selectAllOrders('${params.deptId||''}')">Select all eligible</button></div>${list.map(x=>`<div class="checkbox-row"><input id="order-${x.key}" type="checkbox" ${ui.orderSelection.has(x.key)?'checked':''} ${x.item.existingRequest?'disabled':''} onchange="setOrderSelection('${x.key}',this.checked)"><label for="order-${x.key}"><div class="fixture-head"><div><div class="row-title">${esc(x.item.name)}</div><div class="row-sub">${esc(deptLabel(x.dept.name))} · PO ${esc(x.item.po)} · gap ${x.gap}</div></div>${x.item.existingRequest?badge('REQUEST '+x.item.existingRequest,'blue'):badge('GAP '+x.gap,'red')}</div>${x.item.existingRequest?`<div class="row-sub">An active reorder already exists. Open it rather than creating a duplicate.</div><button class="link-btn" type="button" onclick="event.preventDefault();viewExistingRequest('${x.item.existingRequest}')">View request</button>`:''}</label></div>`).join('')}</div><div class="sticky-action"><button class="primary-btn full" ${ui.orderSelection.size?'':'disabled'} onclick="startSelectedReorder()">Review ${ui.orderSelection.size||''} selected item${ui.orderSelection.size===1?'':'s'}</button></div>`;
}
function selectAllOrders(deptId){collectShortfalls(deptId||null).filter(x=>!x.item.existingRequest).forEach(x=>ui.orderSelection.add(x.key));renderCurrentView()}
function startSelectedReorder(){if(!ui.orderSelection.size)return;openFlow('reorder',{keys:[...ui.orderSelection]})}
function viewExistingRequest(id){toast(`Opened ${id} — status: Submitted`) }
function setTaskTab(tab){ui.taskTab=tab;renderCurrentView()}
function renderTasks(params){
  const p=project();let list=params.deptId?p.tasks.filter(x=>x.department===department(params.deptId).name):p.tasks;
  if(ui.taskTab==='open')list=list.filter(x=>openTaskStates().includes(x.status));
  if(ui.taskTab==='overdue')list=list.filter(x=>openTaskStates().includes(x.status)&&x.due<DEMO_TODAY);
  if(ui.taskTab==='review')list=list.filter(x=>x.status==='PENDING_REVIEW');
  if(ui.taskTab==='history')list=list.filter(x=>['COMPLETED','CANCELLED'].includes(x.status));
  const title=params.deptId?`${deptLabel(department(params.deptId).name)} tasks`:t('tasks');
  return `${pageHead(title,params.deptId?'Department work items':`${p.tasks.filter(x=>openTaskStates().includes(x.status)).length} open tasks`)}<div class="tabs"><button class="tab ${ui.taskTab==='open'?'selected':''}" onclick="setTaskTab('open')">Open</button><button class="tab ${ui.taskTab==='overdue'?'selected':''}" onclick="setTaskTab('overdue')">Overdue</button><button class="tab ${ui.taskTab==='review'?'selected':''}" onclick="setTaskTab('review')">Review</button><button class="tab ${ui.taskTab==='history'?'selected':''}" onclick="setTaskTab('history')">History</button></div><div class="card">${list.length?list.map(x=>`<button class="list-row" style="width:100%;text-align:left" onclick="go('task',{id:'${x.id}'})"><span class="row-icon">${x.status==='PENDING_REVIEW'?'◉':'✓'}</span><span class="row-main"><span class="row-title">${esc(x.title)}</span><span class="row-sub">${esc(deptLabel(x.department))} · ${esc(x.owner)} · ${x.due<DEMO_TODAY&&openTaskStates().includes(x.status)?'OVERDUE ':''}${fmtDate(x.due)}</span></span><span>${badge(x.priority,priorityClass(x.priority))}</span></button>`).join(''):`<div class="empty"><div class="empty-icon">✓</div><div class="empty-title">No tasks in this view</div><div class="empty-text">Try a different status tab or return to the project summary.</div></div>`}</div>`;
}
function renderTaskDetail(params){const x=taskById(params.id);if(!x)return '';return `${pageHead('Task detail',x.id)}<div class="card"><div class="card-title"><span>${esc(x.title)}</span>${badge(x.priority,priorityClass(x.priority))}</div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(x.department))}</span></div><div class="review-row"><span class="review-label">Owner</span><span class="review-value">${esc(x.owner)}</span></div><div class="review-row"><span class="review-label">Due</span><span class="review-value">${fmtDate(x.due)}</span></div><div class="review-row"><span class="review-label">Status</span><span class="review-value">${esc(x.status.replaceAll('_',' '))}</span></div></div><div class="section-title">Update status</div><div class="button-row"><button class="secondary-btn" onclick="updateTaskStatus('${x.id}','IN_PROGRESS')">In progress</button><button class="secondary-btn" onclick="updateTaskStatus('${x.id}','PENDING_REVIEW')">Submit review</button></div><button class="primary-btn full" style="margin-top:8px" onclick="updateTaskStatus('${x.id}','COMPLETED')">Mark complete</button>`}
function updateTaskStatus(id,status){const x=taskById(id);x.status=status;addActivity('task',`${x.title} set to ${status.replaceAll('_',' ')}`,{taskId:id});saveState();toast('Task status updated');renderAll()}
function renderTeam(){const p=project();if(!p.team.length)return `${pageHead(t('team'),'Project roles')}<div class="card empty"><div class="empty-icon">👥</div><div class="empty-title">No team assigned</div><div class="empty-text">Contact Home Office or log a staffing blocker.</div><button class="primary-btn" style="margin-top:14px" onclick="go('contacts')">View Home Office contact</button></div>`;const roles=[...new Set(p.team.map(m=>m.role))];return `${pageHead(t('team'),`${p.team.length} people assigned`)}${roles.map(role=>`<div class="card"><div class="card-title"><span>${esc(role)}</span><span class="card-sub">${p.team.filter(m=>m.role===role).length}</span></div>${p.team.filter(m=>m.role===role).map(m=>`<div class="list-row"><div class="avatar">${initials(m.name)}</div><div class="row-main"><div class="row-title">${esc(m.name)}</div><div class="row-sub">${esc(m.email)} · ${esc(m.phone)}</div><div class="contact-actions"><button class="contact-btn" onclick="toast('Calling ${esc(m.name)}…')">Call</button><button class="contact-btn" onclick="toast('Email draft opened for ${esc(m.name)}')">Email</button></div></div></div>`).join('')}</div>`).join('')}`}
function dominantVendor(d){const counts={};d.fixtures.forEach(i=>counts[i.vendor]=(counts[i.vendor]||0)+1);return Object.keys(counts).sort((a,b)=>counts[b]-counts[a])[0]||null}
function renderContacts(params){const p=project();const d=params.deptId?department(params.deptId):null;const vendor=params.vendor||(d?dominantVendor(d):null);const contacts=[{...p.contacts.homeOffice,type:'Home Office'},{...p.contacts.teamLead,type:'Project team'}];if(vendor)contacts.push({name:vendor,role:'Fixture vendor',email:`support@${vendor.split(' ')[0].toLowerCase()}fixtures.example`,phone:'+1-800-555-0100',type:'Vendor'});return `${pageHead(d?`${deptLabel(d.name)} contacts`:'Escalation contacts',d?'Context-aware routing':'Project leadership and support')}<div class="notice info">The contact list reflects the current project${d?' and selected department':''}. Confirm the responsible item or vendor before sending an escalation.</div>${contacts.map(c=>`<div class="card"><div class="list-row" style="border:0;padding:0"><div class="avatar">${initials(c.name)}</div><div class="row-main"><div class="row-title">${esc(c.name)}</div><div class="row-sub">${esc(c.type)} · ${esc(c.role)}<br>${esc(c.email)} · ${esc(c.phone)}</div><div class="contact-actions"><button class="contact-btn" onclick="toast('Calling ${esc(c.name)}…')">Call</button><button class="contact-btn" onclick="toast('Email opened for ${esc(c.name)}')">Email</button></div></div></div></div>`).join('')}<button class="primary-btn full" onclick="openFlow('escalation',{deptId:'${d?d.id:''}',vendor:'${esc(vendor||'')}'})">Draft escalation</button>`}
function setBlockerTab(tab){ui.blockerTab=tab;renderCurrentView()}
function renderBlockers(){const p=project();let list=p.blockers.filter(b=>ui.blockerTab==='open'?b.status==='OPEN':b.status==='RESOLVED');return `${pageHead(t('blockers'),`${p.openBlockers} open blockers`)}<div class="tabs"><button class="tab ${ui.blockerTab==='open'?'selected':''}" onclick="setBlockerTab('open')">Open</button><button class="tab ${ui.blockerTab==='history'?'selected':''}" onclick="setBlockerTab('history')">Resolution history</button></div><div class="card">${list.length?list.map(b=>`<button class="list-row" style="width:100%;text-align:left" onclick="go('blocker',{id:'${b.id}'})"><span class="row-icon">${b.status==='OPEN'?'🚧':'✓'}</span><span class="row-main"><span class="row-title">${esc(b.title)}</span><span class="row-sub">${esc(deptLabel(b.department))} · ${esc(b.category.replaceAll('_',' '))} · ${fmtDate(b.logged)}</span>${b.resolution?`<span class="row-sub">Resolution: ${esc(b.resolution)}</span>`:''}</span><span>${badge(b.status,b.status==='OPEN'?'red':'green')}</span></button>`).join(''):`<div class="empty"><div class="empty-icon">${ui.blockerTab==='open'?'✓':'📜'}</div><div class="empty-title">${ui.blockerTab==='open'?'No open blockers':'No resolution history'}</div><div class="empty-text">${ui.blockerTab==='open'?'The current project has no active blockers.':'Resolved blockers will appear here.'}</div></div>`}</div><button class="primary-btn full" onclick="openFlow('blocker')">Log a blocker</button>`}
function renderBlockerDetail(params){const b=blockerById(params.id);if(!b)return '';return `${pageHead('Blocker detail',b.id)}<div class="card"><div class="card-title"><span>${esc(b.title)}</span>${badge(b.status,b.status==='OPEN'?'red':'green')}</div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(b.department))}</span></div><div class="review-row"><span class="review-label">Category</span><span class="review-value">${esc(b.category.replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Impact</span><span class="review-value">${esc((b.impact||'PARTIAL').replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Owner</span><span class="review-value">${esc(b.owner)}</span></div><div class="review-row"><span class="review-label">Logged</span><span class="review-value">${fmtDate(b.logged)}</span></div>${b.resolution?`<div class="notice success" style="margin-top:10px"><b>Resolution</b><br>${esc(b.resolution)}</div>`:''}</div><div class="card"><div class="card-title"><span>Activity</span></div>${(b.activity||[]).map(x=>`<div class="list-row"><span class="row-icon">•</span><span class="row-main"><span class="row-title">${esc(x)}</span></span></div>`).join('')}</div>${b.status==='OPEN'?`<div class="button-row"><button class="secondary-btn" onclick="openFlow('escalation',{deptName:'${esc(b.department)}',blockerId:'${b.id}'})">Escalate</button><button class="primary-btn" onclick="openFlow('resolveBlocker',{blockerId:'${b.id}'})">Resolve blocker</button></div>`:''}`}
function renderUpdates(){const p=project();return `${pageHead('Daily updates',`${p.dailyUpdates.length} submitted`)}${p.dailyUpdates.length?p.dailyUpdates.map(u=>`<div class="card"><div class="card-title"><span>${fmtDate(u.date)} · ${esc(u.author)}</span>${u.department?badge(deptLabel(u.department),'blue'):''}</div><div class="row-sub"><b>Completed:</b> ${esc(u.completed||'—')}</div><div class="row-sub"><b>In progress:</b> ${esc(u.progress||'—')}</div><div class="row-sub"><b>Risks:</b> ${esc(u.risks||'None reported')}</div><div class="row-sub"><b>Next:</b> ${esc(u.next||'—')}</div></div>`).join(''):`<div class="card empty"><div class="empty-icon">📝</div><div class="empty-title">No updates submitted</div><div class="empty-text">Submit a structured daily update from Quick actions.</div></div>`}<button class="primary-btn full" onclick="openFlow('dailyUpdate')">Submit daily update</button>`}
function renderHelp(){return `${pageHead('What I can help with','Choose a goal or ask in your own words')}<div class="card"><div class="card-title"><span>Plan work</span></div><div class="button-row"><button class="secondary-btn" onclick="go('phasing')">Phasing plan</button><button class="secondary-btn" onclick="go('risk')">Project risk</button></div></div><div class="card"><div class="card-title"><span>Manage fixtures and shortages</span></div><div class="button-row"><button class="secondary-btn" onclick="go('fixtures')">Fixture status</button><button class="secondary-btn" onclick="go('orders')">Orders needed</button></div></div><div class="card"><div class="card-title"><span>Coordinate execution</span></div><div class="button-row"><button class="secondary-btn" onclick="go('tasks')">Tasks</button><button class="secondary-btn" onclick="go('team')">Team</button></div></div><div class="card"><div class="card-title"><span>Report and resolve</span></div><div class="button-row"><button class="secondary-btn" onclick="go('blockers')">Blockers</button><button class="secondary-btn" onclick="openFlow('dailyUpdate')">Daily update</button></div></div>`}
function openProjectSheet(filter=''){
  const q=filter.toLowerCase();const projects=state.projects.filter(p=>`${p.store} ${p.city} ${p.state} ${p.id} ${p.rpm}`.toLowerCase().includes(q));
  const search=`<div class="sheet-search"><input id="projectSearch" value="${esc(filter)}" placeholder="Search store, city, project or RPM" oninput="openProjectSheet(this.value)"></div>`;
  const body=projects.map(p=>{calcProject(p);return `<button class="sheet-item ${p.id===activeProjectId?'active':''}" onclick="chooseProject('${p.id}')"><span class="sheet-item-icon">${esc(p.store)}</span><span class="sheet-item-copy"><span class="sheet-item-title">${p.focus?'🚩 ':''}Store ${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</span><span class="sheet-item-sub">${esc(p.id)} · RPM ${esc(p.rpm)} · ${p.atRisk} at risk</span></span>${badge(p.atRisk?`${p.atRisk} RISK`:'ON TRACK',p.atRisk?'red':'green')}</button>`}).join('')||`<div class="empty"><div class="empty-icon">⌕</div><div class="empty-title">No projects found</div><div class="empty-text">Try a store number, city, project ID or RPM name.</div></div>`;
  showSheet('Switch project',body,search);setTimeout(()=>{const el=document.getElementById('projectSearch');if(el&&filter)el.focus()},20)
}
function chooseProject(id){
  if(id===activeProjectId){closeSheet();return}
  const p=project();
  if(p.checkedIn){showDialog('You are checked in',`Your active visit is associated with Store ${p.store}. Check out before switching projects.`,[{label:'Stay here',className:'secondary-btn',action:'closeDialog()'},{label:'Review check-out',className:'primary-btn',action:`closeDialog();closeSheet();openFlow('checkout',{switchTo:'${id}'})`}]);return}
  if(p.drafts&&p.drafts.length){showDialog('Saved drafts in this project',`Store ${p.store} has ${p.drafts.length} saved draft(s). They will remain with this project if you switch.`,[{label:'Cancel',className:'secondary-btn',action:'closeDialog()'},{label:'Switch project',className:'primary-btn',action:`closeDialog();switchProject('${id}')`}]);return}
  switchProject(id)
}
function switchProject(id){activeProjectId=id;state.activeProjectId=id;navHistory=[];currentView={screen:'home',params:{}};ui.orderSelection.clear();closeSheet();saveState();renderAll();toast(`Switched to Store ${project().store}`)}
function openLanguageSheet(){showSheet('Language',`<button class="sheet-item ${state.language==='en'?'active':''}" onclick="setLanguage('en')"><span class="sheet-item-icon">EN</span><span class="sheet-item-copy"><span class="sheet-item-title">English</span><span class="sheet-item-sub">Keep the current project and screen</span></span></button><button class="sheet-item ${state.language==='es'?'active':''}" onclick="setLanguage('es')"><span class="sheet-item-icon">ES</span><span class="sheet-item-copy"><span class="sheet-item-title">Español</span><span class="sheet-item-sub">Conservar el proyecto y la pantalla actual</span></span></button>`)}
function setLanguage(lang){state.language=lang;saveState();closeSheet();renderAll();toast(lang==='es'?'Idioma cambiado a español':'Language changed to English')}
function openQuickActions(){
  const p=project();let draftRows='';
  if(p.drafts&&p.drafts.length){draftRows=`<div class="section-title" style="margin:8px 8px 3px">Saved drafts</div>`+p.drafts.map((d,i)=>`<button class="sheet-item" onclick="resumeDraft(${i})"><span class="sheet-item-icon">↺</span><span class="sheet-item-copy"><span class="sheet-item-title">Resume ${esc(flowName(d.type))}</span><span class="sheet-item-sub">Saved ${new Date(d.savedAt).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</span></span></button>`).join('')}
  showSheet(t('quickActions'),`<button class="sheet-item" onclick="closeSheet();startCheckFlow()"><span class="sheet-item-icon">📍</span><span class="sheet-item-copy"><span class="sheet-item-title">${p.checkedIn?'Check out of store':'Check in to store'}</span><span class="sheet-item-sub">${p.checkedIn?'Review the visit before ending it':'Confirm project and location'}</span></span></button><button class="sheet-item" onclick="closeSheet();openFlow('receive')"><span class="sheet-item-icon">▦</span><span class="sheet-item-copy"><span class="sheet-item-title">Scan to receive fixture</span><span class="sheet-item-sub">Verify item, quantity, condition and destination</span></span></button><button class="sheet-item" onclick="closeSheet();openFlow('dailyUpdate')"><span class="sheet-item-icon">📝</span><span class="sheet-item-copy"><span class="sheet-item-title">Submit daily update</span><span class="sheet-item-sub">Progress, risks, next work and support</span></span></button><button class="sheet-item" onclick="closeSheet();openFlow('photo')"><span class="sheet-item-icon">📷</span><span class="sheet-item-copy"><span class="sheet-item-title">Capture photo</span><span class="sheet-item-sub">Attach evidence to a department or record</span></span></button><button class="sheet-item" onclick="closeSheet();openFlow('blocker')"><span class="sheet-item-icon">🚧</span><span class="sheet-item-copy"><span class="sheet-item-title">Log a blocker</span><span class="sheet-item-sub">Add impact, owner and evidence</span></span></button>${draftRows}`)
}
function flowName(type){return ({receive:'fixture receipt',dailyUpdate:'daily update',photo:'photo',blocker:'blocker',reorder:'reorder request',escalation:'escalation'})[type]||type}
function resumeDraft(index){const d=project().drafts.splice(index,1)[0];closeSheet();if(!d)return;flowState=deepClone(d.flowState);flowState.dirty=true;saveState();document.getElementById('flowOverlay').classList.add('open');renderFlow()}
function restartConversation(){
  if(flowState){attemptCloseFlow();return}
  navHistory=[];currentView={screen:'home',params:{}};ui.lastQuery=null;renderAll();toast('Conversation restarted — project actions preserved')
}
function startCheckFlow(){openFlow(project().checkedIn?'checkout':'checkin')}
function notifyTeam(deptId){const d=department(deptId);addActivity('notification',`RPC team notified about ${d.name}`,{deptId});toast(`RPC team notified about ${d.name}`)}
function sendAssistantQuery(explicitText){
  const input=document.getElementById('assistantInput');
  const raw=(typeof explicitText==='string'?explicitText:(input?input.value:'')).trim();
  if(!raw)return;
  if(input)input.value='';
  const q=raw.toLowerCase();
  const d=project().departments.find(x=>q.includes(x.name.toLowerCase())||q.includes(x.id)||q.includes(x.name.split(' ')[0].toLowerCase()));
    if(/pto|sign-off|signoff|approval/.test(q)){go('tasks');toast('Filtered tasks to pending approvals & sign-offs');return}
  if(/called in|call-in|absent|attendance/.test(q)){go('blockers');toast('Attendance & staffing issues in blockers');return}
  if(/team lead schedule|lead schedule|roster/.test(q)){go('team');toast('Viewing team lead and coordinator roster');return}
  if(/collaboration|tools|kairos hub/.test(q)){go('help');return}
  if(/switch|change store|change project|another store/.test(q)){openProjectSheet();return}
  if(/help|what can you|start/.test(q)){go('help');return}
  if(/check.?in|check.?out/.test(q)){startCheckFlow();return}
  if(/daily update|progress note/.test(q)){openFlow('dailyUpdate',d?{deptId:d.id}:{});return}
  if(/log.*blocker|report.*issue|create.*blocker/.test(q)){openFlow('blocker',d?{deptId:d.id}:{});return}
  if(/who.*call|contact|escalat/.test(q)){go('contacts',d?{deptId:d.id}:{});return}
  if(/task|to-do|todo|pending work/.test(q)){go('tasks',d?{deptId:d.id}:{});return}
  if(/order|reorder|shortage|shortfall|gap|quantity/.test(q)){go('orders',d?{deptId:d.id}:{});return}
  if(/fixture|trailer|where|received|location/.test(q)){go('fixtures',d?{deptId:d.id}:{});return}
  if(/risk|delay|behind|late|problem/.test(q)){if(d)go('department',{id:d.id});else go('risk');return}
  if(/phas|schedule|timeline|start date|end date/.test(q)){if(d)go('department',{id:d.id});else go('phasing');return}
  if(/team|coordinator|assigned/.test(q)){go('team');return}
  if(/blocker|open issue|resolution/.test(q)){go('blockers');return}
  if(d){go('department',{id:d.id});return}
  ui.lastQuery=`I need one more detail to help with “${esc(raw)}.” Choose a department or use one of the project shortcuts above.`;navHistory=[];currentView={screen:'home',params:{}};renderAll()
}
function openFlow(type,payload={}){
  const p=project();
  const base={type,step:0,data:deepClone(payload),dirty:false,history:[]};
  if(type==='receive'){base.data.condition='GOOD';base.data.destination='Department';base.data.photoAttached=false;base.data.qty=null}
  if(type==='dailyUpdate'){base.data.department=payload.deptId?department(payload.deptId).name:'';base.data.completed='';base.data.progress='';base.data.risks='';base.data.next='';base.data.support='';base.data.photoAttached=false}
  if(type==='photo'){base.data.imageData='';base.data.fileName='';base.data.association='Department';base.data.department=payload.deptId?department(payload.deptId).name:'';base.data.caption=''}
  if(type==='blocker'){base.data.department=payload.deptId?department(payload.deptId).name:'';base.data.category=payload.fixtureId?'FIXTURE_SHORTAGE':'DELIVERY_DELAY';base.data.impact='SCHEDULE_AT_RISK';base.data.description='';base.data.owner='';base.data.photoAttached=false;base.data.fixtureId=payload.fixtureId||''}
  if(type==='reorder'){base.data.keys=payload.keys||[];base.data.quantities={};base.data.reason='Quantity short vs. plan';base.data.neededBy='2026-09-27';base.data.notes=''}
  if(type==='schedule'){base.data.deptId=payload.deptId;base.data.mode='';base.data.reason='';base.data.notifyTeam=true}
  if(type==='escalation'){base.data.deptId=payload.deptId||'';base.data.deptName=payload.deptName||'';base.data.blockerId=payload.blockerId||'';base.data.vendor=payload.vendor||'';base.data.recipients=['home'];base.data.subject='';base.data.message='';base.data.attachment=false}
  if(type==='resolveBlocker'){base.data.blockerId=payload.blockerId;base.data.resolution='';base.data.resume='YES';base.data.evidence=false}
  if(type==='checkin'){base.data.location='VERIFIED'}
  if(type==='checkout'){base.data.switchTo=payload.switchTo||''}
  flowState=base;document.getElementById('flowOverlay').classList.add('open');closeSheet();renderFlow()
}
function flowMeta(){
  const p=project();const meta={
    receive:{title:'Receive fixture',context:`Store ${p.store} · Verify before posting`,steps:['Verify','Details','Destination','Review']},
    dailyUpdate:{title:'Daily update',context:`Store ${p.store} · Structured field report`,steps:['Progress','Next','Review']},
    photo:{title:'Capture photo',context:`Store ${p.store} · Attach to an operational record`,steps:['Capture','Associate','Review']},
    blocker:{title:'Log blocker',context:`Store ${p.store} · Review before creating`,steps:['Context','Issue','Duplicate','Review']},
    reorder:{title:'Reorder request',context:`Store ${p.store} · Avoid duplicate requests`,steps:['Items','Details','Review']},
    schedule:{title:'Schedule recommendation',context:`Store ${p.store} · Decision support`,steps:['Recommendation','Decision']},
    escalation:{title:'Draft escalation',context:`Store ${p.store} · Review before sending`,steps:['Draft','Review']},
    resolveBlocker:{title:'Resolve blocker',context:`Store ${p.store} · Resolution history`,steps:['Resolution','Review']},
    checkin:{title:'Check in to store',context:`Store ${p.store} — ${p.city}, ${p.state}`,steps:['Confirm']},
    checkout:{title:'Check out of store',context:`Store ${p.store} · Visit summary`,steps:['Review']}
  };return meta[flowState.type]
}
function renderFlow(){
  if(!flowState)return;const m=flowMeta();document.getElementById('flowTitle').textContent=m.title;document.getElementById('flowContext').textContent=m.context;
  document.getElementById('flowBack').style.visibility=flowState.step>0&&!flowState.success?'visible':'hidden';
  const active=Math.min(typeof flowState.step==='number'?flowState.step:0,m.steps.length-1);document.getElementById('flowStepper').innerHTML=flowState.success?'':m.steps.map((s,i)=>`<span class="step-seg ${i<active?'done':i===active?'active':''}"></span>`).join('')+`<span class="step-label">${m.steps[active]||''}</span>`;
  const renderers={receive:renderReceiveFlow,dailyUpdate:renderDailyUpdateFlow,photo:renderPhotoFlow,blocker:renderBlockerFlow,reorder:renderReorderFlow,schedule:renderScheduleFlow,escalation:renderEscalationFlow,resolveBlocker:renderResolveBlockerFlow,checkin:renderCheckinFlow,checkout:renderCheckoutFlow};
  renderers[flowState.type]();
}
function markFlowDirty(){if(flowState)flowState.dirty=true}
function setFlowStep(step){flowState.history.push(flowState.step);flowState.step=step;renderFlow();document.getElementById('flowBody').scrollTop=0}
function flowBack(){if(!flowState)return;if(flowState.history.length){flowState.step=flowState.history.pop();renderFlow()}else if(typeof flowState.step==='number'&&flowState.step>0){flowState.step--;renderFlow()}}
function closeFlow(){flowState=null;document.getElementById('flowOverlay').classList.remove('open');renderAll()}
function attemptCloseFlow(){
  if(!flowState){return}
  if(flowState.success||!flowState.dirty){closeFlow();return}
  showDialog('Leave this flow?','You have unfinished information. Save it as a draft, discard it, or continue editing.',[
    {label:'Continue editing',className:'secondary-btn',action:'closeDialog()'},
    {label:'Save draft',className:'secondary-btn',action:'closeDialog();saveFlowDraft()'},
    {label:'Discard',className:'danger-btn',action:'closeDialog();closeFlow()'}
  ])
}
function saveFlowDraft(){const p=project();p.drafts=p.drafts||[];p.drafts.push({type:flowState.type,savedAt:new Date().toISOString(),flowState:deepClone(flowState)});saveState();closeFlow();toast('Draft saved to this project')}
function flowFooter(secondaryLabel,secondaryAction,primaryLabel,primaryAction,disabled=false){document.getElementById('flowFooter').innerHTML=`${secondaryLabel?`<button class="secondary-btn" onclick="${secondaryAction}">${esc(secondaryLabel)}</button>`:''}<button class="primary-btn" ${disabled?'disabled':''} onclick="${primaryAction}">${esc(primaryLabel)}</button>`}
function successBody(title,text,id=''){return `<div class="flow-success"><div class="success-mark">✓</div><div class="success-title">${esc(title)}</div><div class="success-text">${esc(text)}</div>${id?`<div class="success-id">${esc(id)}</div>`:''}</div>`}
function findFixture(deptId,itemId){const d=department(deptId);return {dept:d,item:d?d.fixtures.find(i=>i.id===itemId):null}}
function allOpenFixtures(deptId){const ds=deptId?[department(deptId)]:project().departments;const out=[];ds.filter(Boolean).forEach(d=>d.fixtures.forEach(i=>{if(gap(i)>0)out.push({dept:d,item:i})}));return out}

function renderCheckinFlow(){
  const p=project();const body=document.getElementById('flowBody');
  if(flowState.success){body.innerHTML=successBody('Checked in',`Your field activity is now associated with Store ${p.store}.`);flowFooter('', '', 'Return to project','closeFlow()');return}
  body.innerHTML=`<div class="card"><div class="card-title"><span>Confirm active store</span>${badge('NOT YET POSTED','blue')}</div><div class="review-row"><span class="review-label">Store</span><span class="review-value">${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</span></div><div class="review-row"><span class="review-label">Project</span><span class="review-value">${esc(p.id)}</span></div><div class="review-row"><span class="review-label">RPM</span><span class="review-value">${esc(p.rpm)}</span></div></div><div class="form-group"><label class="form-label required">Location confirmation</label><div class="choice-grid"><button class="choice ${flowState.data.location==='VERIFIED'?'selected':''}" onclick="flowState.data.location='VERIFIED';markFlowDirty();renderFlow()"><div class="choice-title">Location verified</div><div class="choice-sub">Within the expected store area</div></button><button class="choice ${flowState.data.location==='MANUAL'?'selected':''}" onclick="flowState.data.location='MANUAL';markFlowDirty();renderFlow()"><div class="choice-title">Confirm manually</div><div class="choice-sub">Location services unavailable</div></button></div></div>${flowState.data.location==='MANUAL'?`<div class="notice warn">Manual check-in will be recorded without location verification.</div>`:''}`;
  flowFooter('Cancel','attemptCloseFlow()','Check in','confirmCheckin()')
}
function confirmCheckin(){const p=project();p.checkedIn=true;p.sessionStart=new Date().toISOString();addActivity('checkin',`Checked in to Store ${p.store}`,{sessionStart:p.sessionStart});flowState.dirty=false;flowState.success=true;saveState();renderHeader();renderFlow()}
function renderCheckoutFlow(){
  const p=project();const body=document.getElementById('flowBody');
  if(flowState.success){body.innerHTML=successBody('Checked out',`Your Store ${p.store} visit has ended and the visit summary was saved.`);const switchButton=flowState.data.switchTo?`switchProject('${flowState.data.switchTo}');closeFlow()`:'closeFlow()';flowFooter('', '',flowState.data.switchTo?'Switch project':'Return to project',switchButton);return}
  const since=p.sessionStart?new Date(p.sessionStart).getTime():0;const acts=p.activities.filter(a=>!since||new Date(a.time).getTime()>=since);const counts={receive:acts.filter(a=>a.type==='receive').length,update:acts.filter(a=>a.type==='update').length,photo:acts.filter(a=>a.type==='photo').length,blocker:acts.filter(a=>a.type==='blocker').length};
  body.innerHTML=`<div class="card"><div class="card-title"><span>Visit summary</span>${badge('ACTIVE VISIT','green')}</div><div class="kpi-grid"><div class="kpi"><div class="kpi-number">${counts.receive}</div><div class="kpi-label">Receipts</div></div><div class="kpi"><div class="kpi-number">${counts.update}</div><div class="kpi-label">Updates</div></div><div class="kpi"><div class="kpi-number">${counts.photo}</div><div class="kpi-label">Photos</div></div><div class="kpi"><div class="kpi-number">${counts.blocker}</div><div class="kpi-label">Blockers</div></div></div></div>${p.drafts.length?`<div class="notice warn"><b>${p.drafts.length} saved draft(s) remain.</b><br>They will stay with this project after check-out.</div>`:`<div class="notice success">No unfinished drafts are associated with this visit.</div>`}<div class="card"><div class="review-row"><span class="review-label">Store</span><span class="review-value">${esc(p.store)} — ${esc(p.city)}, ${esc(p.state)}</span></div><div class="review-row"><span class="review-label">Checked in</span><span class="review-value">${p.sessionStart?new Date(p.sessionStart).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):'Unknown'}</span></div><div class="review-row"><span class="review-label">Visit activity</span><span class="review-value">${acts.length} recorded action${acts.length===1?'':'s'}</span></div></div>`;
  flowFooter('Keep visit open','attemptCloseFlow()','Check out','confirmCheckout()')
}
function confirmCheckout(){const p=project();addActivity('checkout',`Checked out of Store ${p.store}`);p.checkedIn=false;p.sessionStart=null;saveState();flowState.dirty=false;flowState.success=true;renderHeader();renderFlow()}

function renderReceiveFlow(){
  const body=document.getElementById('flowBody');const d=flowState.data.deptId?department(flowState.data.deptId):null;const found=flowState.data.itemId?findFixture(flowState.data.deptId,flowState.data.itemId):{dept:null,item:null};const item=found.item;const dept=found.dept;
  if(flowState.success){const result=flowState.data.result;body.innerHTML=successBody(result.exception?'Receipt exception logged':'Fixture receipt posted',result.message,result.id||'')+`${result.exception?`<div class="notice warn"><b>Usable inventory was not increased.</b> Review the linked blocker before continuing department work.</div>`:`<div class="notice success"><b>Updated remaining quantity:</b> ${result.remaining}</div>`}`;document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn" onclick="undoReceive()">Undo</button><button class="primary-btn" onclick="closeFlow();go('fixtures',{deptId:'${result.deptId}'})">View department</button>`;return}
  if(flowState.step===0){
    const options=allOpenFixtures(flowState.data.deptId).map(x=>`<option value="${x.dept.id}::${x.item.id}" ${flowState.data.itemId===x.item.id?'selected':''}>${esc(x.dept.name)} — ${esc(x.item.name)} · gap ${gap(x.item)}</option>`).join('');
    body.innerHTML=`<div class="scan-zone"><div class="scan-icon">▦</div><div class="scan-title">Scan a fixture, PO or trailer label</div><div class="scan-text">The item must match the active store before a receipt can be posted.</div><button class="secondary-btn" onclick="simulateReceiveScan()">Simulate scan</button></div><div class="form-group" style="margin-top:13px"><label class="form-label">Or select an expected fixture</label><select class="select" onchange="setReceiveItem(this.value)"><option value="">Choose a fixture line</option>${options}</select></div>${item?`<div class="notice success"><b>Match found:</b> ${esc(item.name)} · PO ${esc(item.po)} · ${esc(dept.name)}</div>`:''}`;
    flowFooter('Cancel','attemptCloseFlow()','Continue','receiveNext()',!item);return
  }
  if(flowState.step===1){
    body.innerHTML=`<div class="card"><div class="card-title"><span>${esc(item.name)}</span>${badge(itemStatusText(item.status),itemStatusClass(item.status))}</div><div class="review-row"><span class="review-label">Expected remaining</span><span class="review-value">${gap(item)}</span></div><div class="review-row"><span class="review-label">PO / trailer</span><span class="review-value">${esc(item.po)} / ${esc(item.trailer)}</span></div></div><div class="form-group"><label class="form-label required">Quantity received</label><input id="receiveQty" class="input" type="number" min="1" max="${gap(item)+10}" value="${flowState.data.qty||gap(item)}" oninput="markFlowDirty()"><div class="form-hint">Expected remaining: ${gap(item)}. An overage requires confirmation.</div><div id="receiveQtyError"></div></div><div class="form-group"><label class="form-label required">Condition</label><div class="choice-grid">${[['GOOD','Good','Ready to use'],['DAMAGED','Damaged','Photo and blocker recommended'],['INCORRECT','Incorrect item','Do not add to usable inventory'],['DISCREPANCY','Quantity discrepancy','Record the count exception']].map(([v,l,s])=>`<button class="choice ${flowState.data.condition===v?'selected':''}" onclick="chooseReceiveCondition('${v}')"><div class="choice-title">${l}</div><div class="choice-sub">${s}</div></button>`).join('')}</div></div>`;
    flowFooter('Back','flowBack()','Continue','receiveNext()');return
  }
  if(flowState.step===2){
    body.innerHTML=`<div class="form-group"><label class="form-label required">Destination</label><select id="receiveDestination" class="select" onchange="markFlowDirty()"><option ${flowState.data.destination==='Department'?'selected':''}>Department</option><option ${flowState.data.destination==='Staging area'?'selected':''}>Staging area</option><option ${flowState.data.destination==='Backroom'?'selected':''}>Backroom</option><option ${flowState.data.destination==='Remain on trailer'?'selected':''}>Remain on trailer</option></select></div><div class="form-group"><label class="form-label">Evidence</label><button class="choice ${flowState.data.photoAttached?'selected':''}" style="width:100%" onclick="flowState.data.photoAttached=!flowState.data.photoAttached;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.photoAttached?'✓ Photo attached':'Attach a photo'}</div><div class="choice-sub">Recommended for damage, incorrect items and discrepancies</div></button></div>${flowState.data.condition!=='GOOD'&&!flowState.data.photoAttached?`<div class="notice warn">Attach a photo before posting an exception when possible.</div>`:''}`;
    flowFooter('Back','flowBack()','Review receipt','receiveNext()');return
  }
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review fixture receipt</span>${badge(flowState.data.condition==='GOOD'?'READY TO POST':'EXCEPTION','blue')}</div><div class="review-row"><span class="review-label">Store</span><span class="review-value">${esc(project().store)}</span></div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(dept.name))}</span></div><div class="review-row"><span class="review-label">Fixture</span><span class="review-value">${esc(item.name)}</span></div><div class="review-row"><span class="review-label">Quantity</span><span class="review-value">${flowState.data.qty}</span></div><div class="review-row"><span class="review-label">Condition</span><span class="review-value">${esc(flowState.data.condition.replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Destination</span><span class="review-value">${esc(flowState.data.destination)}</span></div><div class="review-row"><span class="review-label">Photo</span><span class="review-value">${flowState.data.photoAttached?'Attached':'Not attached'}</span></div></div>${flowState.data.qty>gap(item)?`<div class="notice warn"><b>Over-receipt:</b> ${flowState.data.qty-gap(item)} above the expected quantity. Confirm only if the physical count is correct.</div>`:''}`;
  flowFooter('Back','flowBack()',flowState.data.condition==='GOOD'?'Post receipt':'Log exception','confirmReceive()')
}
function simulateReceiveScan(){const first=allOpenFixtures(flowState.data.deptId)[0];if(!first)return toast('No open fixture lines');flowState.data.deptId=first.dept.id;flowState.data.itemId=first.item.id;markFlowDirty();renderFlow()}
function setReceiveItem(value){if(!value){flowState.data.itemId='';renderFlow();return}const [deptId,itemId]=value.split('::');flowState.data.deptId=deptId;flowState.data.itemId=itemId;markFlowDirty();renderFlow()}
function chooseReceiveCondition(value){flowState.data.condition=value;markFlowDirty();renderFlow()}
function receiveNext(){
  if(flowState.step===0){setFlowStep(1);return}
  if(flowState.step===1){const found=findFixture(flowState.data.deptId,flowState.data.itemId);const el=document.getElementById('receiveQty');const qty=Number(el.value);if(!qty||qty<1){document.getElementById('receiveQtyError').innerHTML='<div class="error-text">Enter a quantity of at least 1.</div>';return}if(qty>gap(found.item)+10){document.getElementById('receiveQtyError').innerHTML='<div class="error-text">Quantity is too far above the expected amount.</div>';return}flowState.data.qty=qty;markFlowDirty();setFlowStep(2);return}
  if(flowState.step===2){flowState.data.destination=document.getElementById('receiveDestination').value;markFlowDirty();setFlowStep(3)}
}
function confirmReceive(){
  const {dept,item}=findFixture(flowState.data.deptId,flowState.data.itemId);flowState.data.original={received:item.received,status:item.status,location:item.location,blockerCount:project().blockers.length};const qty=flowState.data.qty;let result;
  if(flowState.data.condition==='GOOD'){
    item.received=Math.min(item.ordered,item.received+qty);item.status=item.received>=item.ordered?'RECEIVED':'PARTIAL';item.location=`${item.status==='RECEIVED'?'Received':'Partially received'} — ${flowState.data.destination}`;calcProject(project());addActivity('receive',`${qty} ${item.name} received for ${dept.name}`,{deptId:dept.id,itemId:item.id,qty});result={exception:false,message:`${qty} unit${qty===1?'':'s'} of ${item.name} were posted to ${dept.name}.`,remaining:gap(item),deptId:dept.id};
  }else{
    const id=nextBlockerId(project());const cat=flowState.data.condition==='DAMAGED'?'FIXTURE_SHORTAGE':'OTHER';project().blockers.unshift({id,department:dept.name,category:cat,title:`${flowState.data.condition.replaceAll('_',' ')} — ${item.name}`,impact:'PARTIAL',owner:'Home Office',status:'OPEN',logged:DEMO_TODAY,resolution:null,activity:['Created from fixture receiving exception']});addActivity('blocker',`Receipt exception logged for ${item.name}`,{deptId:dept.id,blockerId:id});result={exception:true,message:`The ${flowState.data.condition.toLowerCase().replaceAll('_',' ')} receipt was linked to a new blocker.`,id,remaining:gap(item),deptId:dept.id};
  }
  flowState.data.result=result;flowState.dirty=false;flowState.success=true;saveState();renderHeader();renderFlow()
}
function undoReceive(){const {dept,item}=findFixture(flowState.data.deptId,flowState.data.itemId);const o=flowState.data.original;if(!o)return;if(flowState.data.result.exception&&project().blockers.length>o.blockerCount)project().blockers.splice(0,project().blockers.length-o.blockerCount);item.received=o.received;item.status=o.status;item.location=o.location;calcProject(project());addActivity('undo',`Fixture receipt undone for ${item.name}`,{deptId:dept.id,itemId:item.id});saveState();toast('Receipt undone');closeFlow();go('fixtures',{deptId:dept.id})}
function renderDailyUpdateFlow(){
  const body=document.getElementById('flowBody');
  if(flowState.success){const u=flowState.data.result;body.innerHTML=successBody('Daily update submitted',`The update was saved to Store ${project().store} and is available in project history.`,u.id);flowFooter('View history','closeFlow();go(\'updates\')','Return to project','closeFlow()');return}
  if(flowState.step===0){
    body.innerHTML=`<div class="form-group"><label class="form-label">Department context</label><select id="updateDepartment" class="select" onchange="markFlowDirty()"><option value="">Project-wide update</option>${project().departments.map(d=>`<option value="${esc(d.name)}" ${flowState.data.department===d.name?'selected':''}>${esc(deptLabel(d.name))}</option>`).join('')}</select></div><div class="form-group"><label class="form-label required">Work completed today</label><textarea id="updateCompleted" class="textarea" placeholder="What was completed?" oninput="markFlowDirty()">${esc(flowState.data.completed)}</textarea></div><div class="form-group"><label class="form-label required">Work in progress</label><textarea id="updateProgress" class="textarea" placeholder="What is still underway?" oninput="markFlowDirty()">${esc(flowState.data.progress)}</textarea></div><div class="form-group"><label class="form-label">Risks or blockers</label><textarea id="updateRisks" class="textarea" placeholder="Describe active risks, or enter None" oninput="markFlowDirty()">${esc(flowState.data.risks)}</textarea><div id="updateError"></div></div>`;
    flowFooter('Cancel','attemptCloseFlow()','Continue','dailyUpdateNext()');return
  }
  if(flowState.step===1){
    body.innerHTML=`<div class="form-group"><label class="form-label required">Work planned next</label><textarea id="updateNext" class="textarea" placeholder="What will happen next?" oninput="markFlowDirty()">${esc(flowState.data.next)}</textarea></div><div class="form-group"><label class="form-label">Support required</label><textarea id="updateSupport" class="textarea" placeholder="What support or decision is needed?" oninput="markFlowDirty()">${esc(flowState.data.support)}</textarea></div><div class="form-group"><label class="form-label">Evidence</label><button class="choice ${flowState.data.photoAttached?'selected':''}" style="width:100%" onclick="flowState.data.photoAttached=!flowState.data.photoAttached;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.photoAttached?'✓ Photo attached':'Attach a photo'}</div><div class="choice-sub">Optional supporting evidence for the update</div></button></div>`;
    flowFooter('Back','flowBack()','Review update','dailyUpdateNext()');return
  }
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review daily update</span>${badge('DRAFT','blue')}</div><div class="review-row"><span class="review-label">Scope</span><span class="review-value">${flowState.data.department?esc(deptLabel(flowState.data.department)):'Project-wide'}</span></div><div class="review-row"><span class="review-label">Completed</span><span class="review-value">${esc(flowState.data.completed)}</span></div><div class="review-row"><span class="review-label">In progress</span><span class="review-value">${esc(flowState.data.progress)}</span></div><div class="review-row"><span class="review-label">Risks</span><span class="review-value">${esc(flowState.data.risks||'None reported')}</span></div><div class="review-row"><span class="review-label">Next</span><span class="review-value">${esc(flowState.data.next)}</span></div><div class="review-row"><span class="review-label">Support</span><span class="review-value">${esc(flowState.data.support||'None requested')}</span></div><div class="review-row"><span class="review-label">Photo</span><span class="review-value">${flowState.data.photoAttached?'Attached':'Not attached'}</span></div></div>`;
  flowFooter('Back','flowBack()','Submit update','confirmDailyUpdate()')
}
function dailyUpdateNext(){
  if(flowState.step===0){const completed=document.getElementById('updateCompleted').value.trim();const progress=document.getElementById('updateProgress').value.trim();if(!completed||!progress){document.getElementById('updateError').innerHTML='<div class="error-text">Add completed work and work in progress before continuing.</div>';return}flowState.data.department=document.getElementById('updateDepartment').value;flowState.data.completed=completed;flowState.data.progress=progress;flowState.data.risks=document.getElementById('updateRisks').value.trim();markFlowDirty();setFlowStep(1);return}
  if(flowState.step===1){const next=document.getElementById('updateNext').value.trim();if(!next){toast('Add the work planned next');return}flowState.data.next=next;flowState.data.support=document.getElementById('updateSupport').value.trim();markFlowDirty();setFlowStep(2)}
}
function confirmDailyUpdate(){const p=project();const id=`UPD-${String(p.dailyUpdates.length+1).padStart(3,'0')}`;const u={id,date:DEMO_TODAY,author:p.rpm,...deepClone(flowState.data)};delete u.result;p.dailyUpdates.unshift(u);addActivity('update',`Daily update ${id} submitted`,{updateId:id});flowState.data.result={id};flowState.success=true;flowState.dirty=false;saveState();renderFlow()}

function renderPhotoFlow(){
  const body=document.getElementById('flowBody');
  if(flowState.success){const r=flowState.data.result;body.innerHTML=successBody('Photo attached',`The image was linked to ${r.association.toLowerCase()} context for Store ${project().store}.`,r.id);flowFooter('', '', 'Return to project','closeFlow()');return}
  if(flowState.step===0){
    body.innerHTML=`<div class="photo-preview" id="photoPreview">${flowState.data.imageData?`<img src="${flowState.data.imageData}" alt="Selected evidence">`:`<div class="photo-placeholder">📷</div>`}</div><div class="button-row" style="margin-top:10px"><label class="secondary-btn" style="cursor:pointer">Choose photo<input type="file" accept="image/*" capture="environment" style="display:none" onchange="handlePhotoFile(event)"></label><button class="secondary-btn" onclick="simulatePhoto()">Simulate capture</button></div><div class="form-hint">The prototype keeps the preview in this browser session only.</div>`;
    flowFooter('Cancel','attemptCloseFlow()','Continue','photoNext()',!flowState.data.imageData);return
  }
  if(flowState.step===1){
    body.innerHTML=`<div class="form-group"><label class="form-label required">Attach to</label><select id="photoAssociation" class="select" onchange="markFlowDirty()"><option ${flowState.data.association==='Department'?'selected':''}>Department</option><option ${flowState.data.association==='Fixture'?'selected':''}>Fixture</option><option ${flowState.data.association==='Task'?'selected':''}>Task</option><option ${flowState.data.association==='Blocker'?'selected':''}>Blocker</option><option ${flowState.data.association==='Daily update'?'selected':''}>Daily update</option></select></div><div class="form-group"><label class="form-label required">Department</label><select id="photoDepartment" class="select" onchange="markFlowDirty()"><option value="">Select department</option>${project().departments.map(d=>`<option value="${esc(d.name)}" ${flowState.data.department===d.name?'selected':''}>${esc(deptLabel(d.name))}</option>`).join('')}</select></div><div class="form-group"><label class="form-label required">Caption</label><textarea id="photoCaption" class="textarea" placeholder="What does this photo show?" oninput="markFlowDirty()">${esc(flowState.data.caption)}</textarea><div id="photoError"></div></div>`;
    flowFooter('Back','flowBack()','Review photo','photoNext()');return
  }
  body.innerHTML=`<div class="photo-preview"><img src="${flowState.data.imageData}" alt="Evidence preview"></div><div class="card" style="margin-top:10px"><div class="review-row"><span class="review-label">File</span><span class="review-value">${esc(flowState.data.fileName||'captured-photo.jpg')}</span></div><div class="review-row"><span class="review-label">Attach to</span><span class="review-value">${esc(flowState.data.association)}</span></div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(flowState.data.department))}</span></div><div class="review-row"><span class="review-label">Caption</span><span class="review-value">${esc(flowState.data.caption)}</span></div></div>`;
  flowFooter('Back','flowBack()','Attach photo','confirmPhoto()')
}
function handlePhotoFile(event){const file=event.target.files&&event.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{flowState.data.imageData=reader.result;flowState.data.fileName=file.name;markFlowDirty();renderFlow()};reader.readAsDataURL(file)}
function simulatePhoto(){flowState.data.imageData='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="360"><rect width="600" height="360" fill="#dce9f6"/><rect x="65" y="90" width="470" height="210" rx="16" fill="#ffffff"/><rect x="95" y="120" width="180" height="150" fill="#0071dc" opacity=".2"/><rect x="300" y="120" width="205" height="36" rx="8" fill="#0071dc" opacity=".6"/><rect x="300" y="173" width="160" height="22" rx="6" fill="#8798aa" opacity=".5"/><rect x="300" y="212" width="190" height="22" rx="6" fill="#8798aa" opacity=".35"/><circle cx="185" cy="195" r="42" fill="#ffc220"/><text x="300" y="275" font-family="Arial" font-size="20" fill="#041f41">Fixture evidence preview</text></svg>`);flowState.data.fileName='fixture-evidence.jpg';markFlowDirty();renderFlow()}
function photoNext(){if(flowState.step===0){setFlowStep(1);return}if(flowState.step===1){const dept=document.getElementById('photoDepartment').value;const caption=document.getElementById('photoCaption').value.trim();if(!dept||!caption){document.getElementById('photoError').innerHTML='<div class="error-text">Select a department and add a caption.</div>';return}flowState.data.association=document.getElementById('photoAssociation').value;flowState.data.department=dept;flowState.data.caption=caption;markFlowDirty();setFlowStep(2)}}
function confirmPhoto(){const id=`PHOTO-${Math.floor(1000+Math.random()*9000)}`;addActivity('photo',`Photo attached to ${flowState.data.association}: ${flowState.data.caption}`,{photoId:id,department:flowState.data.department});flowState.data.result={id,association:flowState.data.association};flowState.success=true;flowState.dirty=false;saveState();renderFlow()}
function recommendedOwner(category){return category==='DELIVERY_DELAY'?'Fixture vendor':category==='STAFFING'?'RPC team lead':'Home Office'}
function renderBlockerFlow(){
  const body=document.getElementById('flowBody');
  if(flowState.success){const r=flowState.data.result;body.innerHTML=successBody('Blocker created',`The issue was added to ${r.department} and routed to ${r.owner}.`,r.id);document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn" onclick="closeFlow();go('blockers')">View blockers</button><button class="primary-btn" onclick="closeFlow();go('blocker',{id:'${r.id}'})">View blocker</button>`;return}
  if(flowState.step===0){
    body.innerHTML=`<div class="form-group"><label class="form-label required">Department</label><select id="blockerDepartment" class="select" onchange="markFlowDirty()"><option value="">Select department</option>${project().departments.map(d=>`<option value="${esc(d.name)}" ${flowState.data.department===d.name?'selected':''}>${esc(deptLabel(d.name))}</option>`).join('')}</select></div><div class="form-group"><label class="form-label required">Category</label><select id="blockerCategory" class="select" onchange="markFlowDirty()"><option value="DELIVERY_DELAY" ${flowState.data.category==='DELIVERY_DELAY'?'selected':''}>Delivery delay</option><option value="FIXTURE_SHORTAGE" ${flowState.data.category==='FIXTURE_SHORTAGE'?'selected':''}>Fixture shortage</option><option value="SCOPE_CHANGE" ${flowState.data.category==='SCOPE_CHANGE'?'selected':''}>Scope change</option><option value="STAFFING" ${flowState.data.category==='STAFFING'?'selected':''}>Staffing</option><option value="OTHER" ${flowState.data.category==='OTHER'?'selected':''}>Other</option></select></div><div class="form-group"><label class="form-label required">Operational impact</label><div class="choice-grid">${[['WORK_STOPPED','Work stopped','Department work cannot continue'],['SCHEDULE_AT_RISK','Schedule at risk','Dates may be affected'],['PARTIAL','Partial impact','Work can continue with constraints'],['INFORMATIONAL','Informational','Track with no current impact']].map(([v,l,s])=>`<button class="choice ${flowState.data.impact===v?'selected':''}" onclick="flowState.data.impact='${v}';markFlowDirty();renderFlow()"><div class="choice-title">${l}</div><div class="choice-sub">${s}</div></button>`).join('')}</div><div id="blockerContextError"></div></div>`;
    flowFooter('Cancel','attemptCloseFlow()','Continue','blockerNext()');return
  }
  if(flowState.step===1){
    const owner=flowState.data.owner||recommendedOwner(flowState.data.category);
    body.innerHTML=`<div class="form-group"><label class="form-label required">Describe the issue</label><textarea id="blockerDescription" class="textarea" placeholder="What happened, what is affected, and what is needed?" oninput="markFlowDirty()">${esc(flowState.data.description)}</textarea></div><div class="form-group"><label class="form-label required">Suggested owner</label><select id="blockerOwner" class="select" onchange="markFlowDirty()"><option ${owner==='Home Office'?'selected':''}>Home Office</option><option ${owner==='Fixture vendor'?'selected':''}>Fixture vendor</option><option ${owner==='RPC team lead'?'selected':''}>RPC team lead</option></select><div class="form-hint">Suggested from the selected category. You can change it.</div></div><div class="form-group"><label class="form-label">Evidence</label><button class="choice ${flowState.data.photoAttached?'selected':''}" style="width:100%" onclick="flowState.data.photoAttached=!flowState.data.photoAttached;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.photoAttached?'✓ Photo attached':'Attach a photo'}</div><div class="choice-sub">Recommended for fixture, delivery and scope issues</div></button></div><div id="blockerIssueError"></div>`;
    flowFooter('Back','flowBack()','Check for duplicates','blockerNext()');return
  }
  if(flowState.step===2){
    const dup=blockerById(flowState.data.duplicateId);
    body.innerHTML=`<div class="notice warn"><b>Possible duplicate found.</b><br>Review the existing blocker before creating another record.</div><div class="card"><div class="card-title"><span>${esc(dup.title)}</span>${badge(dup.status,'red')}</div><div class="review-row"><span class="review-label">ID</span><span class="review-value">${esc(dup.id)}</span></div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(dup.department))}</span></div><div class="review-row"><span class="review-label">Category</span><span class="review-value">${esc(dup.category.replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Owner</span><span class="review-value">${esc(dup.owner)}</span></div></div><div class="button-row"><button class="secondary-btn" onclick="openDuplicateBlocker('${dup.id}')">Open existing</button><button class="primary-btn" onclick="ackDuplicate()">Create separate blocker</button></div>${flowState.data.duplicateAcknowledged?`<div class="notice info" style="margin-top:10px">You confirmed this is a separate issue. Continue to review the new blocker.</div>`:''}`;
    flowFooter('Back','flowBack()','Continue to review','blockerNext()',!flowState.data.duplicateAcknowledged);return
  }
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review blocker</span>${badge(flowState.data.impact.replaceAll('_',' '),flowState.data.impact==='WORK_STOPPED'?'red':'amber')}</div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(flowState.data.department))}</span></div><div class="review-row"><span class="review-label">Category</span><span class="review-value">${esc(flowState.data.category.replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Impact</span><span class="review-value">${esc(flowState.data.impact.replaceAll('_',' '))}</span></div><div class="review-row"><span class="review-label">Issue</span><span class="review-value">${esc(flowState.data.description)}</span></div><div class="review-row"><span class="review-label">Owner</span><span class="review-value">${esc(flowState.data.owner)}</span></div><div class="review-row"><span class="review-label">Photo</span><span class="review-value">${flowState.data.photoAttached?'Attached':'Not attached'}</span></div></div>`;
  flowFooter('Back','flowBack()','Create blocker','confirmBlocker()')
}
function blockerNext(){
  if(flowState.step===0){const dept=document.getElementById('blockerDepartment').value;if(!dept){document.getElementById('blockerContextError').innerHTML='<div class="error-text">Select a department before continuing.</div>';return}flowState.data.department=dept;flowState.data.category=document.getElementById('blockerCategory').value;flowState.data.owner=recommendedOwner(flowState.data.category);markFlowDirty();setFlowStep(1);return}
  if(flowState.step===1){const desc=document.getElementById('blockerDescription').value.trim();if(desc.length<8){document.getElementById('blockerIssueError').innerHTML='<div class="error-text">Add enough detail to distinguish and route the issue.</div>';return}flowState.data.description=desc;flowState.data.owner=document.getElementById('blockerOwner').value;const dup=project().blockers.find(b=>b.status==='OPEN'&&b.department===flowState.data.department&&b.category===flowState.data.category);flowState.data.duplicateId=dup?dup.id:'';flowState.data.duplicateAcknowledged=!dup;markFlowDirty();setFlowStep(dup?2:3);return}
  if(flowState.step===2&&flowState.data.duplicateAcknowledged){setFlowStep(3)}
}
function ackDuplicate(){flowState.data.duplicateAcknowledged=true;markFlowDirty();renderFlow()}
function openDuplicateBlocker(id){closeFlow();go('blocker',{id})}
function confirmBlocker(){const p=project();const id=nextBlockerId(p);const b={id,department:flowState.data.department,category:flowState.data.category,title:flowState.data.description,impact:flowState.data.impact,owner:flowState.data.owner,status:'OPEN',logged:DEMO_TODAY,resolution:null,activity:['Created in RPM Assistant',flowState.data.photoAttached?'Photo attached':'No photo attached']};p.blockers.unshift(b);addActivity('blocker',`Blocker ${id} created`,{blockerId:id,department:b.department});flowState.data.result={id,department:b.department,owner:b.owner};flowState.success=true;flowState.dirty=false;saveState();renderHeader();renderFlow()}

function shortfallByKey(key){const [deptId,itemId]=key.split('::');const d=department(deptId);const item=d&&d.fixtures.find(i=>i.id===itemId);return d&&item?{dept:d,item,key,gap:gap(item)}:null}
function renderReorderFlow(){
  const body=document.getElementById('flowBody');
  if(flowState.success){const r=flowState.data.result;body.innerHTML=successBody('Reorder request submitted',`${r.itemCount} line item${r.itemCount===1?' was':'s were'} routed for review.`,r.id)+`<div class="notice info"><b>Status:</b> Submitted · <b>Needed by:</b> ${fmtDate(r.neededBy)}</div>`;document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn" onclick="toast('Request ${r.id} opened')">View request</button><button class="primary-btn" onclick="closeFlow();go('orders')">Return to shortages</button>`;return}
  const eligible=collectShortfalls(null).filter(x=>!x.item.existingRequest);const selected=flowState.data.keys.map(shortfallByKey).filter(Boolean);
  if(flowState.step===0){
    body.innerHTML=`<div class="notice info">Select only the items that belong in this request. Lines with an active request are excluded.</div><div class="card">${eligible.map(x=>`<div class="checkbox-row"><input id="flow-order-${x.key}" type="checkbox" ${flowState.data.keys.includes(x.key)?'checked':''} onchange="toggleReorderKey('${x.key}',this.checked)"><label for="flow-order-${x.key}"><div class="row-title">${esc(x.item.name)}</div><div class="row-sub">${esc(deptLabel(x.dept.name))} · PO ${esc(x.item.po)} · gap ${x.gap}</div></label></div>`).join('')}</div>`;
    flowFooter('Cancel','attemptCloseFlow()',`Continue with ${selected.length||''} item${selected.length===1?'':'s'}`,'reorderNext()',!selected.length);return
  }
  if(flowState.step===1){
    body.innerHTML=`<div class="card"><div class="card-title"><span>Requested quantities</span><span class="card-sub">${selected.length} lines</span></div>${selected.map(x=>`<div class="form-group"><label class="form-label">${esc(x.item.name)} · gap ${x.gap}</label><input id="rq-${x.key}" class="input" type="number" min="1" max="${x.gap}" value="${flowState.data.quantities[x.key]||x.gap}" oninput="markFlowDirty()"></div>`).join('')}</div><div class="form-group"><label class="form-label required">Needed by</label><input id="reorderNeededBy" class="input" type="date" value="${esc(flowState.data.neededBy)}" oninput="markFlowDirty()"></div><div class="form-group"><label class="form-label required">Reason</label><select id="reorderReason" class="select" onchange="markFlowDirty()"><option ${flowState.data.reason==='Quantity short vs. plan'?'selected':''}>Quantity short vs. plan</option><option ${flowState.data.reason==='Damaged on receipt'?'selected':''}>Damaged on receipt</option><option ${flowState.data.reason==='Scope change'?'selected':''}>Scope change</option><option ${flowState.data.reason==='Incorrect item received'?'selected':''}>Incorrect item received</option></select></div><div class="form-group"><label class="form-label">Notes or evidence</label><textarea id="reorderNotes" class="textarea" placeholder="Add context for sourcing or approval" oninput="markFlowDirty()">${esc(flowState.data.notes)}</textarea><div id="reorderError"></div></div>`;
    flowFooter('Back','flowBack()','Review request','reorderNext()');return
  }
  const total=selected.reduce((s,x)=>s+(flowState.data.quantities[x.key]||0),0);
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review reorder request</span>${badge(`${selected.length} LINES`,'blue')}</div>${selected.map(x=>`<div class="review-row"><span class="review-label">${esc(x.item.name)}<br>${esc(deptLabel(x.dept.name))}</span><span class="review-value">${flowState.data.quantities[x.key]} units</span></div>`).join('')}<div class="review-row"><span class="review-label">Total quantity</span><span class="review-value">${total}</span></div><div class="review-row"><span class="review-label">Needed by</span><span class="review-value">${fmtDate(flowState.data.neededBy)}</span></div><div class="review-row"><span class="review-label">Reason</span><span class="review-value">${esc(flowState.data.reason)}</span></div><div class="review-row"><span class="review-label">Notes</span><span class="review-value">${esc(flowState.data.notes||'None')}</span></div></div><div class="notice warn">Submitting creates an operational request. Quantities and scope cannot be changed without updating the request.</div>`;
  flowFooter('Back','flowBack()','Submit request','confirmReorder()')
}
function toggleReorderKey(key,checked){if(checked&&!flowState.data.keys.includes(key))flowState.data.keys.push(key);if(!checked)flowState.data.keys=flowState.data.keys.filter(k=>k!==key);markFlowDirty();renderFlow()}
function reorderNext(){
  if(flowState.step===0){setFlowStep(1);return}
  if(flowState.step===1){const selected=flowState.data.keys.map(shortfallByKey).filter(Boolean);for(const x of selected){const n=Number(document.getElementById('rq-'+x.key).value);if(!n||n<1||n>x.gap){document.getElementById('reorderError').innerHTML='<div class="error-text">Each quantity must be between 1 and the current gap.</div>';return}flowState.data.quantities[x.key]=n}const needed=document.getElementById('reorderNeededBy').value;if(!needed){document.getElementById('reorderError').innerHTML='<div class="error-text">Select a needed-by date.</div>';return}flowState.data.neededBy=needed;flowState.data.reason=document.getElementById('reorderReason').value;flowState.data.notes=document.getElementById('reorderNotes').value.trim();markFlowDirty();setFlowStep(2)}
}
function confirmReorder(){const p=project();const id=`RQ-${Math.floor(40000+Math.random()*50000)}`;const lines=flowState.data.keys.map(shortfallByKey).filter(Boolean).map(x=>({department:x.dept.name,itemId:x.item.id,item:x.item.name,quantity:flowState.data.quantities[x.key],po:x.item.po}));lines.forEach(l=>{const d=p.departments.find(x=>x.name===l.department);const i=d.fixtures.find(x=>x.id===l.itemId);i.existingRequest=id});p.reorderRequests.unshift({id,status:'SUBMITTED',created:DEMO_TODAY,neededBy:flowState.data.neededBy,reason:flowState.data.reason,notes:flowState.data.notes,lines});addActivity('reorder',`Reorder ${id} submitted`,{requestId:id,lineCount:lines.length});flowState.data.result={id,itemCount:lines.length,neededBy:flowState.data.neededBy};flowState.success=true;flowState.dirty=false;ui.orderSelection.clear();saveState();renderFlow()}
function renderScheduleFlow(){
  const body=document.getElementById('flowBody');const d=department(flowState.data.deptId);const r=d&&d.recommendation;
  if(!d||!r){body.innerHTML='<div class="notice danger">No schedule recommendation is available.</div>';flowFooter('', '', 'Close','closeFlow()');return}
  if(flowState.success){
    const mode=flowState.data.result.mode;const title=mode==='apply'?'Schedule updated':mode==='approval'?'Approval request submitted':'Recommendation dismissed';const text=mode==='apply'?`${d.name} now runs ${fmtDate(d.start)}–${fmtDate(d.end)}. Team notification was ${flowState.data.notifyTeam?'included':'not included'}.`:mode==='approval'?`The proposed shift was sent to ${project().contacts.homeOffice.name} because the go-live buffer would tighten to ${r.buffer}.`:`The recommendation was dismissed and the reason was retained in the decision history.`;
    body.innerHTML=successBody(title,text,flowState.data.result.id||'');document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn" onclick="closeFlow();go('department',{id:'${d.id}'})">View department</button><button class="primary-btn" onclick="closeFlow();go('phasing')">View phasing</button>`;return
  }
  if(flowState.step===0){
    body.innerHTML=`<div class="card"><div class="card-title"><span>${esc(deptLabel(d.name))}</span>${badge(d.risk,riskClass(d.risk))}</div><div class="row-sub"><b>Reason:</b> ${esc(d.reason?d.reason.text:'Schedule adjustment recommended.')}</div><div class="date-compare" style="margin-top:12px"><div class="date-box"><div class="date-caption">Current</div><div class="date-value">${fmtDate(r.oldStart)}–${fmtDate(r.oldEnd)}</div></div><div class="date-arrow">→</div><div class="date-box new"><div class="date-caption">Suggested</div><div class="date-value">${fmtDate(r.newStart)}–${fmtDate(r.newEnd)}</div></div></div><div class="review-row" style="margin-top:8px"><span class="review-label">Shift</span><span class="review-value">${r.shiftDays} days</span></div><div class="review-row"><span class="review-label">Ripple effect</span><span class="review-value">${esc(r.ripple)}</span></div><div class="review-row"><span class="review-label">Go-live buffer</span><span class="review-value">${esc(r.buffer)}</span></div></div>${r.critical?`<div class="notice danger"><b>Approval required.</b><br>The proposed dates leave a critical go-live buffer and cannot be directly applied.</div>`:`<div class="notice info"><b>Decision remains with the RPM.</b><br>Review the operational impact before applying, dismissing or escalating.</div>`}<div class="action-grid"><button class="action-tile" onclick="scheduleChoice('apply')"><div class="action-icon">✓</div><div class="action-label">${r.critical?'Send for approval':'Apply recommendation'}</div><div class="action-desc">${r.critical?'Route the date change':'Update phasing after review'}</div></button><button class="action-tile" onclick="scheduleChoice('dismiss')"><div class="action-icon">×</div><div class="action-label">Dismiss</div><div class="action-desc">Keep current dates and record reason</div></button><button class="action-tile" onclick="scheduleChoice('escalate')"><div class="action-icon">✉</div><div class="action-label">Escalate instead</div><div class="action-desc">Draft a message with impact details</div></button><button class="action-tile" onclick="closeFlow();go('fixtures',{deptId:'${d.id}'})"><div class="action-icon">▦</div><div class="action-label">Review evidence</div><div class="action-desc">Inspect fixture and order status</div></button></div>`;
    document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn full" onclick="attemptCloseFlow()">Close without decision</button>`;return
  }
  if(flowState.data.mode==='dismiss'){
    body.innerHTML=`<div class="notice info">The current dates will remain unchanged. The reason will be recorded with the recommendation.</div><div class="form-group"><label class="form-label required">Reason for dismissal</label><select id="scheduleDismissReason" class="select" onchange="markFlowDirty()"><option>Waiting for updated ETA</option><option>Issue already resolved</option><option>Recommendation is not operationally feasible</option><option>Other</option></select></div><div class="form-group"><label class="form-label">Decision notes</label><textarea id="scheduleNotes" class="textarea" placeholder="Add supporting context" oninput="markFlowDirty()">${esc(flowState.data.reason)}</textarea></div>`;
    flowFooter('Back','flowBack()','Dismiss recommendation','confirmScheduleDecision()');return
  }
  const approval=r.critical;
  body.innerHTML=`<div class="card"><div class="card-title"><span>${approval?'Approval request':'Apply schedule change'}</span>${badge(approval?'CRITICAL BUFFER':'READY TO APPLY',approval?'red':'blue')}</div><div class="review-row"><span class="review-label">Department</span><span class="review-value">${esc(deptLabel(d.name))}</span></div><div class="review-row"><span class="review-label">Current dates</span><span class="review-value">${fmtDate(r.oldStart)}–${fmtDate(r.oldEnd)}</span></div><div class="review-row"><span class="review-label">Proposed dates</span><span class="review-value">${fmtDate(r.newStart)}–${fmtDate(r.newEnd)}</span></div><div class="review-row"><span class="review-label">Ripple</span><span class="review-value">${esc(r.ripple)}</span></div><div class="review-row"><span class="review-label">Go-live buffer</span><span class="review-value">${esc(r.buffer)}</span></div>${approval?`<div class="review-row"><span class="review-label">Approver</span><span class="review-value">${esc(project().contacts.homeOffice.name)}</span></div>`:''}</div><div class="form-group"><button class="choice ${flowState.data.notifyTeam?'selected':''}" style="width:100%" onclick="flowState.data.notifyTeam=!flowState.data.notifyTeam;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.notifyTeam?'✓ Notify project team':'Notify project team'}</div><div class="choice-sub">Send the decision and updated dates after completion</div></button></div>${approval?`<div class="notice danger">This action submits the proposed dates for approval. The current phasing plan will remain unchanged until approved.</div>`:`<div class="notice warn">Confirming updates the department dates. The change will be recorded in project activity.</div>`}`;
  flowFooter('Back','flowBack()',approval?'Submit for approval':'Apply dates','confirmScheduleDecision()')
}
function scheduleChoice(mode){if(mode==='escalate'){const deptId=flowState.data.deptId;closeFlow();openFlow('escalation',{deptId});return}flowState.data.mode=mode;markFlowDirty();setFlowStep(1)}
function confirmScheduleDecision(){const d=department(flowState.data.deptId);const r=d.recommendation;let mode=flowState.data.mode;let id='';if(mode==='dismiss'){flowState.data.reason=document.getElementById('scheduleDismissReason').value+(document.getElementById('scheduleNotes').value.trim()?`: ${document.getElementById('scheduleNotes').value.trim()}`:'');r.status='DISMISSED';r.decisionReason=flowState.data.reason;addActivity('schedule',`Recommendation dismissed for ${d.name}`,{deptId:d.id});}
  else if(r.critical){mode='approval';id=`APR-${Math.floor(10000+Math.random()*80000)}`;r.status='PENDING_APPROVAL';r.approvalId=id;addActivity('schedule',`Schedule approval ${id} submitted for ${d.name}`,{deptId:d.id,approvalId:id});}
  else{mode='apply';d.start=r.newStart;d.end=r.newEnd;r.status='APPLIED';addActivity('schedule',`Schedule shifted for ${d.name}`,{deptId:d.id});if(flowState.data.notifyTeam)addActivity('notification',`Project team notified of ${d.name} date change`,{deptId:d.id});}
  flowState.data.result={mode,id};flowState.success=true;flowState.dirty=false;saveState();renderFlow()
}

function escalationContext(){const p=project();const d=flowState.data.deptId?department(flowState.data.deptId):null;const b=flowState.data.blockerId?blockerById(flowState.data.blockerId):null;const deptName=d?d.name:(flowState.data.deptName||b?.department||'Project');const vendor=flowState.data.vendor||(d?dominantVendor(d):'');return {p,d,b,deptName,vendor}}
function prepareEscalationDraft(){if(flowState.data.subject)return;const {p,d,b,deptName}=escalationContext();const issue=b?b.title:(d&&d.reason?d.reason.text:'Operational support needed');flowState.data.subject=`Store ${p.store} — ${deptName} support needed`;flowState.data.message=`Hello,\n\nStore ${p.store} (${p.id}) needs support for ${deptName}.\n\nIssue: ${issue}\nImpact: ${b?(b.impact||'Operational impact under review'):(d?`${d.risk}; ${d.fixturePct}% of fixtures received`:'Project execution risk')}\nRequested action: Please confirm ownership, next step, and expected resolution date.\n\nThank you,\n${p.rpm}`}
function renderEscalationFlow(){
  prepareEscalationDraft();const body=document.getElementById('flowBody');const ctx=escalationContext();
  if(flowState.success){const r=flowState.data.result;body.innerHTML=successBody('Escalation sent',`The message was sent to ${r.recipientText} and recorded in project activity.`,r.id);flowFooter('', '', 'Return to project','closeFlow()');return}
  if(flowState.step===0){
    const recipients=[['home',ctx.p.contacts.homeOffice.name+' · Home Office'],['team',ctx.p.contacts.teamLead.name+' · Project team']];if(ctx.vendor)recipients.push(['vendor',ctx.vendor+' · Fixture vendor']);
    body.innerHTML=`<div class="notice info">Review and edit the draft before sending. No message is sent until you confirm the next step.</div><div class="form-group"><label class="form-label required">Recipients</label>${recipients.map(([v,l])=>`<div class="checkbox-row"><input id="rec-${v}" type="checkbox" ${flowState.data.recipients.includes(v)?'checked':''} onchange="toggleEscalationRecipient('${v}',this.checked)"><label for="rec-${v}"><div class="row-title">${esc(l)}</div></label></div>`).join('')}</div><div class="form-group"><label class="form-label required">Subject</label><input id="escalationSubject" class="input" value="${esc(flowState.data.subject)}" oninput="markFlowDirty()"></div><div class="form-group"><label class="form-label required">Message</label><textarea id="escalationMessage" class="textarea" style="min-height:170px" oninput="markFlowDirty()">${esc(flowState.data.message)}</textarea></div><div class="form-group"><button class="choice ${flowState.data.attachment?'selected':''}" style="width:100%" onclick="flowState.data.attachment=!flowState.data.attachment;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.attachment?'✓ Evidence attached':'Attach supporting evidence'}</div><div class="choice-sub">Photo, fixture status or blocker summary</div></button></div><div id="escalationError"></div>`;
    flowFooter('Cancel','attemptCloseFlow()','Review message','escalationNext()');return
  }
  const names=flowState.data.recipients.map(r=>r==='home'?ctx.p.contacts.homeOffice.name:r==='team'?ctx.p.contacts.teamLead.name:ctx.vendor).filter(Boolean);
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review escalation</span>${badge('NOT SENT','blue')}</div><div class="review-row"><span class="review-label">To</span><span class="review-value">${esc(names.join(', '))}</span></div><div class="review-row"><span class="review-label">Subject</span><span class="review-value">${esc(flowState.data.subject)}</span></div><div class="review-row"><span class="review-label">Message</span><span class="review-value" style="white-space:pre-line">${esc(flowState.data.message)}</span></div><div class="review-row"><span class="review-label">Evidence</span><span class="review-value">${flowState.data.attachment?'Attached':'Not attached'}</span></div></div>`;
  flowFooter('Back','flowBack()','Send escalation','confirmEscalation()')
}
function toggleEscalationRecipient(v,checked){if(checked&&!flowState.data.recipients.includes(v))flowState.data.recipients.push(v);if(!checked)flowState.data.recipients=flowState.data.recipients.filter(x=>x!==v);markFlowDirty()}
function escalationNext(){const subject=document.getElementById('escalationSubject').value.trim();const message=document.getElementById('escalationMessage').value.trim();if(!flowState.data.recipients.length||!subject||!message){document.getElementById('escalationError').innerHTML='<div class="error-text">Select at least one recipient and complete the subject and message.</div>';return}flowState.data.subject=subject;flowState.data.message=message;markFlowDirty();setFlowStep(1)}
function confirmEscalation(){const ctx=escalationContext();const id=`ESC-${Math.floor(10000+Math.random()*80000)}`;const names=flowState.data.recipients.map(r=>r==='home'?ctx.p.contacts.homeOffice.name:r==='team'?ctx.p.contacts.teamLead.name:ctx.vendor).filter(Boolean);addActivity('escalation',`Escalation ${id} sent: ${flowState.data.subject}`,{escalationId:id,recipients:names});if(ctx.b){ctx.b.activity=ctx.b.activity||[];ctx.b.activity.push(`Escalation ${id} sent`)}flowState.data.result={id,recipientText:names.join(', ')};flowState.success=true;flowState.dirty=false;saveState();renderFlow()}

function renderResolveBlockerFlow(){
  const body=document.getElementById('flowBody');const b=blockerById(flowState.data.blockerId);
  if(!b){body.innerHTML='<div class="notice danger">Blocker not found.</div>';flowFooter('', '', 'Close','closeFlow()');return}
  if(flowState.success){body.innerHTML=successBody('Blocker resolved',`${b.id} was moved to resolution history and relevant users were notified.`,b.id);document.getElementById('flowFooter').innerHTML=`<button class="secondary-btn" onclick="closeFlow();go('blockers')">View history</button><button class="primary-btn" onclick="closeFlow();go('blocker',{id:'${b.id}'})">View blocker</button>`;return}
  if(flowState.step===0){
    body.innerHTML=`<div class="card"><div class="card-title"><span>${esc(b.title)}</span>${badge('OPEN','red')}</div><div class="row-sub">${esc(deptLabel(b.department))} · ${esc(b.owner)}</div></div><div class="form-group"><label class="form-label required">Resolution</label><textarea id="blockerResolution" class="textarea" placeholder="What resolved the issue?" oninput="markFlowDirty()">${esc(flowState.data.resolution)}</textarea></div><div class="form-group"><label class="form-label required">Can work resume?</label><div class="choice-grid"><button class="choice ${flowState.data.resume==='YES'?'selected':''}" onclick="flowState.data.resume='YES';markFlowDirty();renderFlow()"><div class="choice-title">Yes</div><div class="choice-sub">Department work can continue</div></button><button class="choice ${flowState.data.resume==='NO'?'selected':''}" onclick="flowState.data.resume='NO';markFlowDirty();renderFlow()"><div class="choice-title">No</div><div class="choice-sub">Follow-up action remains</div></button></div></div><div class="form-group"><button class="choice ${flowState.data.evidence?'selected':''}" style="width:100%" onclick="flowState.data.evidence=!flowState.data.evidence;markFlowDirty();renderFlow()"><div class="choice-title">${flowState.data.evidence?'✓ Resolution evidence attached':'Attach resolution evidence'}</div><div class="choice-sub">Photo, confirmation or delivery receipt</div></button></div><div id="resolveError"></div>`;
    flowFooter('Cancel','attemptCloseFlow()','Review resolution','resolveBlockerNext()');return
  }
  body.innerHTML=`<div class="card"><div class="card-title"><span>Review resolution</span>${badge(flowState.data.resume==='YES'?'WORK CAN RESUME':'FOLLOW-UP NEEDED',flowState.data.resume==='YES'?'green':'amber')}</div><div class="review-row"><span class="review-label">Blocker</span><span class="review-value">${esc(b.id)}</span></div><div class="review-row"><span class="review-label">Resolution</span><span class="review-value">${esc(flowState.data.resolution)}</span></div><div class="review-row"><span class="review-label">Work resume</span><span class="review-value">${flowState.data.resume==='YES'?'Yes':'No — follow-up remains'}</span></div><div class="review-row"><span class="review-label">Evidence</span><span class="review-value">${flowState.data.evidence?'Attached':'Not attached'}</span></div></div>${flowState.data.resume==='NO'?`<div class="notice warn">The blocker will be resolved, but the record will note that follow-up work remains.</div>`:''}`;
  flowFooter('Back','flowBack()','Confirm resolution','confirmResolveBlocker()')
}
function resolveBlockerNext(){const resolution=document.getElementById('blockerResolution').value.trim();if(resolution.length<8){document.getElementById('resolveError').innerHTML='<div class="error-text">Describe the resolution before continuing.</div>';return}flowState.data.resolution=resolution;markFlowDirty();setFlowStep(1)}
function confirmResolveBlocker(){const b=blockerById(flowState.data.blockerId);b.status='RESOLVED';b.resolution=flowState.data.resolution;b.resolved=DEMO_TODAY;b.activity=b.activity||[];b.activity.push(`Resolved by ${project().rpm}`,flowState.data.evidence?'Resolution evidence attached':'No evidence attached',flowState.data.resume==='YES'?'Work can resume':'Follow-up work remains');addActivity('blocker',`Blocker ${b.id} resolved`,{blockerId:b.id});flowState.success=true;flowState.dirty=false;saveState();renderHeader();renderFlow()}

